export const TARBIYAH_SERIES = {"title":"Raising Our Children as God Intended: A Guide to Islamic Child Raising (Tarbiyah)","speaker":"Shaykh Usama Abdulghani","channel":"Light Of Guidance","playlist":"https://www.youtube.com/playlist?list=PL6wktQtsoJqwoAJaZWRfQHZQfdzw8Mn5D","parts":16,"hours":14.5,"source":"Sixteen analysis documents written for Tafseer from the transcripts, each audited against al-Kafi (with al-Majlisi's and Behbudi's gradings), al-Mizan, Majma' al-Bayan, Nahj al-Balagha and the Sunni corpus. Every narration carries its grading; the speaker's book-learned citations are strong, his orally transmitted stories are where the failures cluster."};
export const TARBIYAH_NO_REPEAT: { claim: string; where: string; what: string; parts: number[] }[] = [{"claim":"The Tabuk hand-kiss — the Prophet (s) kisses the labourer's calloused hand: \"this hand the Fire will never touch\"","where":"Part 13","what":"Graded mawdu' (fabricated) by Ibn al-Jawzi and kadhib by al-Dhahabi. The value it teaches is well supported elsewhere; the story is not.","parts":[13]},{"claim":"«لا يكذب الكاذب إلا من مهانة نفسه» — \"None lies but out of the lowliness of his own soul\"","where":"Part 14 — the sentence the whole lecture rests on","what":"Not a hadith. Absent from al-Kafi's 22-hadith bab al-kidhb; dorar.net returns no result. Its only traceable home is a chapter heading in Ibn 'Adi's al-Kamil fi Ma'rifat Du'afa' al-Muhaddithin, bab 23 — a hadith critic's dictum about why narrators fabricate.","parts":[14]},{"claim":"«أدِّ الأمانةَ إلى من ائتمنك ولا تخن من خانك» — introduced as \"This is from Rasulullah\"","where":"Part 15 — the lecture's opening hadith","what":"Imam Ahmad declared it batil. Ibn al-Jawzi: all three Companion routes invalid. Abu Hatim: munkar. al-Shafi'i: laysa bi-thabit. Ibn Hazm: la yasihh. Only al-Tirmidhi 1264 dissents. No Imami chain located.","parts":[15]},{"claim":"\"Intellect is the imam of the body, imagination is its soldier\"","where":"Part 13","what":"Not a hadith. A philosophical lineage: Ibn Sina → al-Ghazali → Imam Khomeini's Sharh.","parts":[13]},{"claim":"\"Dirt is the springtime of children\" (al-turab rabi' al-sibyan), told with a scene of the Prophet (s) stopping a companion","where":"Part 11","what":"No Shia source at all. Appears only at al-Tabarani, al-Mu'jam al-Kabir 6/140 no. 5775, and is discussed inside Sunni hadith criticism under suspicion of fabrication. The narrative frame is not transmitted either.","parts":[11]},{"claim":"\"Love is the foundation of my way\" (al-hubbu asasi), given as Prophetic","where":"Parts 3, 7, 8","what":"Not located in any collection, Shia or Sunni.","parts":[3,7,8]},{"claim":"\"Whoever withholds a right Allah imposed will spend twice as much later\"","where":"Parts 3, 7","what":"Not located anywhere.","parts":[3,7]},{"claim":"\"Kissing your child raises you a daraja, and between each daraja is 500 years\"","where":"Parts 3, 10","what":"The real text (al-Kafi 6:49 ch.35 h.1) gives a hasana, one good deed — not a rank; the 500 years is spliced in from an unrelated narration family; al-Majlisi grades the base text da'if. Kiss your children — do not price it.","parts":[3,10]},{"claim":"\"Shaking hands with children is a sunnah\"","where":"Part 10","what":"Not attested anywhere. A completed negative.","parts":[10]},{"claim":"\"The elite soldiers of Imam Mahdi\" as a narration","where":"Part 6","what":"Not a narration.","parts":[6]},{"claim":"«الكذب والخيانة ليسا من أخلاق الكرام»","where":"Part 14","what":"No attestation at all.","parts":[14]},{"claim":"The \"Chinese proverb\" about the best time to plant a tree","where":"Part 8","what":"Not Chinese. Earliest trace: Cleveland Plain Dealer, March 1967, anonymous.","parts":[8]},{"claim":"Claim","where":"Where","what":"The literature","parts":[]},{"claim":"Gaming addiction is 10–30% of children","where":"Part 13","what":"3.05% / 1.96% (Stevens et al., ANZJP 2021); 0.3–1.0% (Przybylski et al., AJP 2017). Off by an order of magnitude.","parts":[13]},{"claim":"Sugar makes children hyperactive","where":"Part 7","what":"23 double-blind RCTs clear sugar (JAMA 1995). The real culprits are artificial colourings + sodium benzoate (Lancet 2007) and caffeine — both in his own Cheetos-and-soda example. The strongest finding is that the expectancy effect sits in the parent (Hoover & Milich 1994).","parts":[7]},{"claim":"\"Michigan gives you twelve weeks of maternity leave\"","where":"Part 5","what":"Michigan has no such statute; it is federal FMLA, unpaid, with eligibility thresholds many workers fail. Iran — where he sets the story — mandates nine months paid. The real figure served his argument better.","parts":[5]},{"claim":"Screens will make a child stop wanting to play","where":"Part 9","what":"Displacement is real but small (r ≈ −0.1). \"Grit\" and \"instant gratification\" are unsupported here and both constructs have taken replication damage (Credé 2017; Watts 2018). Mood effects are real, small and bidirectional (Orben & Przybylski 2019: ≈0.4% of variance).","parts":[9]},{"claim":"Lazy eye: the window slams shut","where":"Part 9","what":"You patch the strong eye, and PEDIG (Arch Ophthalmol 2005) found children aged 7–17 still respond. The window narrows; it does not close.","parts":[9]},{"claim":"Restricting play breaks sibling relationships","where":"Part 10","what":"No evidence links play restriction to sibling relationship breakdown. This is the load-bearing beam of his longest case study.","parts":[10]},{"claim":"Siblings should be no more than three years apart","where":"Part 4","what":"Not evidence-based (Frontiers in Pediatrics 2022 review: no optimal interval). He correctly hedges it to \"some scholars.\"","parts":[4]}];
export const TARBIYAH: TarbiyahLecture[] = [{"n":1,"slug":"lecture-01-challenges-and-the-warm-home","title":"Challenges to Tarbiyah & The Warm, Inviting Home","video":"WRisv9rc-bI","minutes":91,"thesis":"Islamic tarbiyah is a system — with defined goals, defined stages, and defined methods — not a set of good intentions. Most parenting failure among practising Muslim families is not a failure of sincerity but a failure of knowledge and sequencing: the right thing done at the wrong age, or the right goal pursued by a method Islam never prescribed. And the system works inside out: the first person it reforms is the parent, not the child.","why":"This lecture reframes parenting from managing a child to rebuilding a household. Almost every practical instruction in it is an instruction to the parent about the parent: lower your standard of living, put down the phone, model the obedience you want to receive, thank your spouse, adjust your expectations, bite your tongue in front of the kids. That reframing is the foundation the remaining fifte","topics":[{"t":"Encouragement before diagnosis","a":124,"b":549},{"t":"Challenge 1: Not knowing that Islam has a tarbiyah system","a":549,"b":1036},{"t":"Challenge 2: Uncritical adoption of Western psychology","a":1036,"b":1522},{"t":"Challenges 3 & 4: Competitors for attention, and media as educator","a":1522,"b":1826},{"t":"Challenges 5 & 6: Too little time, too little motivation","a":1826,"b":2502},{"t":"Challenge 7: The modern lifestyle","a":2502,"b":2988},{"t":"Solution 1: The warm and inviting home — five conditions","a":2988,"b":3834},{"t":"The imperfect spouse","a":4198,"b":4564},{"t":"Q&A","a":4564,"b":5413}],"takeaways":["Tarbiyah is a system with stages, goals and methods — sincerity is not a substitute for knowing it.","Your children are an amanah; you are answerable for effort, not outcome.","Tarbiyah is inside out — the first person it reforms is you.","The right value at the wrong age does damage.","Chores are not the relationship. Engaged time is.","A child who does not find rahma at home will find it outside — and whoever supplies it shapes them.","Overreaction teaches lying — in children and in spouses.","You cannot demand obedience you have not modelled.","Never correct your spouse in front of the children.","Community service that consumes your children's time is a miscalculation."],"principles":["Tarbiyah is a system — learn it.","Tarbiyah is inside out — you change first.","You own the effort; Allah owns the outcome.","Right value, wrong age = damage.","Chores ≠ relationship. Engaged time is.","Model it before you demand it.","Honour truth-telling above a clean record.","Never correct your spouse in front of the children.","If they don't find rahma here, they'll find it there.","It's harder to build than to destroy — and cheaper to build early."],"nuggets":[{"q":"We're trying to reverse engineer Qasim.","ts":2623,"note":"The clearest one-line statement of the series' goal."},{"q":"Islamic tarbiyah is inside out.","ts":1948,"note":"The idea that reorganises everything else."},{"q":"When I discipline the mother, a weakened mother is hurting the kid.","ts":4381,"note":"The sentence that should end every argument in front of children."},{"q":"Do you think sometimes we, as parents, can teach our children to hide things from us by overreacting?","ts":3349,"note":"And then, devastatingly: \"Do you think spouses can teach one another to lie to them?\" [57:52]"}],"practices":["Engaged time, counted. A fixed block per child — no phone in hand, no chore running in parallel. Sitting, playing, talking. For Eliyya (4) this is floor-level play; for Abbas (7) it is conversation, a game, or a shared task he chose.","Say it out loud. \"I love you\" to each child and to your spouse, daily, in words — not only in provision. [51:48]","Thank the means. Every meal cooked, every trip to work, every bin taken out gets named and thanked. Children copy what they see modelled between the parents. [58:52]","Truth over offence. Whenever a child discloses a mistake, the first sentence out of your mouth is about the disclosure: \"You told me the truth. That matters more.\" Then deal with the mistake.","Phone discipline in front of the children. They are watching the phone as much as they are watching you. [29:26]"],"questions":{"parent":["In the last seven days, how many minutes did I spend with each child that were engaged — nothing else in my hands, no agenda?","When my child last told me an uncomfortable truth, what did my face do first?","Which of the seven challenges is actually the binding constraint in my house — and which one am I using as an excuse for a different one?"],"spouse":["Which of the five conditions of a warm home is weakest in our house — love, respect, trust, appreciation, or Allah first?","Have either of us taught the other to hide things by overreacting? Name a specific occasion.","Do our children ever see or hear us disagreeing? What have they seen in the last month?"],"family":["What makes our house feel warm? What makes it feel cold?","When you make a mistake, is it easy or hard to tell me? What would make it easier?","Who else teaches you things besides us — screens, friends, teachers, videos? What do they teach?"]},"activities":{"abbas":["The Trust Box (discussion)","The Truth Ledger (character-building)","\"Who Is Teaching Me?\" (real-life challenge)","The Qasim Story (story activity)","Activity B1 — The Lut Question (character-building)","Activity B2 — Shake the Tree (discussion + real task)"],"eliyya":["\"I Love You Because\" (emotional development)","Mud, Water, Green (play-based learning)","Thank-You Rounds (Islamic manners)","The Telling-Game (parent-child bonding)","Floor Time (parent-child bonding)","Allah Made That (Islamic manners, play-based)"]},"corrections":[{"claim":"Children are an amanah to be returned","status":"⚠ Partly supported","note":"Al-Mizan does hold amanat extends beyond property — but says nothing about children here, and the verse reads \"to their owners,\" not \"to Allah.\" Legitimate homily; not tafsir."},{"claim":"Purity itself becomes the offence","status":"✅ Verified","note":"⚠ Wording is آلَ لُوطٍ, not 'ala Lut. Al-Mizan: mockery."},{"claim":"God provides for children and parents","status":"✅ Verified (verse)","note":"⚠ The 17:31 vs 6:151 \"two situations\" reading is Ibn 'Ashur / Ibn Kathir, absent from al-Mizan and Majma' al-Bayan."},{"claim":"Sakinah increases faith","status":"✅ Strongly verified","note":"⚠ Do not tie v.4 specifically to Bay'at al-Ridwan; al-Mizan does not."},{"claim":"Shake the tree; God provides","status":"⚠ Principle sound, source wrong","note":"Absent from al-Mizan and Majma' al-Bayan. Sourceable to Makarim Shirazi, Nemuneh."},{"claim":"Well-raised children shield parents from the Fire","status":"❌ Meaning inverted","note":"Text real (Thawab al-A'mal 178) but it is bereavement literature — children who died. Chain also weak. Most important correction in this audit."}],"counts":{"verses":9,"narrations":27,"audit":39}},{"n":2,"slug":"lecture-02-founding-principles-and-tarbiyah-by-observation","title":"The Founding Principles & Tarbiyah Through Observation","video":"4UqbGXdlz10","minutes":70,"thesis":"Islamic tarbiyah is not a technique bolted onto a child — it is the deliberate clearing of ground so that something already inside the child can grow. Shaykh Usama gives the definition twice, and the second version is the load-bearing one:","why":"Part 1 diagnosed the problem and built the environment. Part 2 supplies the theory that makes the practice non-arbitrary — and lands on the most demanding instruction in the series so far: before you correct the child, examine what the child has been watching. The dinner-table case study, replayed seven years later with the son delivering the father's exact lines back to the mother, is the most ef","topics":[{"t":"What tarbiyah is, and what it is for","a":21,"b":568},{"t":"The objection: does worship-centred upbringing produce underachievers?","a":629,"b":872},{"t":"The fitrah, and the parent as obstacle","a":872,"b":1603},{"t":"Islam as an indivisible package","a":1967,"b":2706},{"t":"Tarbiyah through observation: the first method","a":2706,"b":3681},{"t":"The characteristics of learning through observation","a":3681,"b":4171}],"takeaways":["Tarbiyah is clearing ground, not installing software.","The goal is an 'abd of Allah — and that single change reorganises what you worry about.","You have failed only if you did not do your part.","Excellence is still required — but powered by love of Allah, not fear of loss.","When a small child misbehaves, look at yourself first.","The love you deposit in years 0–7 is what powers every discipline tool later.","Your intention does not control the message.","Children learn what is shameful by watching, and it sets before argument can reach it.","Halal income shows up in the children.","Command them only what you command yourself."],"principles":["Tarbiyah is clearing ground for something already there.","The goal is an 'abd — and that changes what you measure.","You own the effort, not the outcome.","Look at yourself first — without being militant about it.","The system is indivisible; borrowed tools don't work.","Deposit love before you need to withdraw.","Your intention doesn't travel. Your behaviour does.","It starts in infancy and the compass sets early.","Command them only what you command yourself.","It's not about what you say. People say a lot of things."],"nuggets":[{"q":"Tarbiyah is preparing the grounds for the fitrah to flourish and blossom, in order for that child to achieve the purpose of their creation.","ts":1115,"note":"The definition the whole series rests on."},{"q":"If you want to fix your son's behaviour, then you need to stop being an obstacle to the fitra that Allah placed in him.","ts":1481,"note":"The end of the Socratic case study, and the hardest sentence in the lecture."},{"q":"I might have to make sure that I'm not the obstacle. I'm not the bad example.","ts":568,"note":""},{"q":"The message of the behaviour is not necessarily the one that we intended.","ts":3742,"note":"Which is why muraqabah is a parenting skill."}],"practices":["Worship where they can see it. Pray, recite, and — the part most parents skip — talk to Allah out loud in front of them. Let the children grow up seeing that their parents worship a living God, not perform a routine. [55:13]","The salah handover. When a small child interrupts your prayer, set them down gently and continue. When they are hungry at prayer time, feed them first. Eliyya's association with namaz is being built right now, and it is being built out of these moments. [49:08]","Keep the promises you make to children. This is the half of \"ahibbu al-sibyan\" that gets left out — \"for they know nothing except that it is you who provide for them.\"","Salaam first, to the children, before anything else — before asking about dinner, before sitting down. The dinner-table case study turns entirely on this. [60:21]","Thank the cook, out loud, even when the food is wrong. \"The food is wonderful, jazakallahu khayr\" is a tarbiyah act, not a courtesy."],"questions":{"parent":["If the goal is that Abbas and Eliyya become servants of Allah, what am I currently measuring them by instead?","What does my face do when the adhan sounds? What have they learned from it?","Name a behaviour of theirs I dislike. Where, specifically, did they see it?"],"spouse":["What is each of us modelling that the other would rather the children didn't copy?","Are we agreed that the goal is servanthood — and does our actual weekly schedule reflect that?","What are our children's associations with salah right now? List them honestly, one each."],"family":["What do you think Allah made us for?","What do you notice about how Mama and Baba act when it's time to pray?","What is something you've learned from watching us that we never actually taught you?"]},"activities":{"abbas":["The Watching Week (discussion + real-life challenge)","The Purpose Conversation (discussion)","The Promise Ledger (character-building)","Halal Detective (real-life challenge)","The Higher Path (character-building)"],"eliyya":["Her Own Mohr (play-based, Islamic manners)","The Salaam Game (Islamic manners, bonding)","Out-Loud Du'a (bonding, emotional development)","Promises Kept (emotional development)","Freedom and the Red Line (play-based)","\"What Did You See?\" (bonding)"]},"corrections":[{"claim":"Purpose of creation is 'ubudiyyah","status":"✅ Strongly verified","note":"al-Mizan: creation has a purpose and it is worship. ⚠ The \"obedience\" gloss is Majma' al-Bayan's, not al-Mizan's"},{"claim":"Children are born on the fitrah","status":"✅ Strongly verified","note":"⚠ al-Mizan reads la tabdil as fact, not prohibition — the fitrah is obscured, not changed"},{"claim":"Fitrah includes Muhammad's nubuwwah","status":"❌ Not located","note":"Not in that chapter; h.4 glosses fitrah as recognising Allah as Creator"},{"claim":"Every child born on the fitrah until parents…","status":"✅ Verified — Sunni","note":"Bukhari 1385 / Muslim 2658. ⚠ al-Kafi's recension omits the parents clause"},{"claim":"Obey Me and I'll make you like Me","status":"❌ Chainless, late","note":"'Uddat al-Da'i → Bihar 90:376; traced to Ikhwan al-Safa"},{"claim":"\"I become his hearing, sight, tongue\"","status":"✅ Strongly verified","note":"al-Kafi 2:352 h.8, sahih (al-Majlisi). ⚠ A separate narration — the two were spliced"}],"counts":{"verses":6,"narrations":16,"audit":31}},{"n":3,"slug":"lecture-03-tarbiyah-through-interaction-and-intense-love","title":"Tarbiyah Through Interaction: Making a Child Feel Intensely Loved","video":"Gmd4W08ZttM","minutes":82,"thesis":"Loving your child is not the same thing as your child feeling loved — and only the second one does the work of tarbiyah. Shaykh Usama opens the second method of upbringing, tarbiyah through interaction, with a claim he does not hedge:","why":"Part 1 built the environment, Part 2 supplied the theory, and Part 3 is the first lecture in the series that hands a parent something to do tonight and a reason the doing works. Its centre of gravity is a reversal most religious parents need: the child's demands for attention, play, freedom and notice are not misbehaviour to be managed but needs Allah placed in the fitrah [60:58], and the parent w","topics":[{"t":"Why this is worth your time: legacy, and the arithmetic of delay","a":1,"b":365},{"t":"The fourth characteristic: how a moral compass gets set","a":365,"b":668},{"t":"Case study: the Muhammadi family","a":668,"b":972},{"t":"The second method: two messages in every interaction","a":972,"b":1279},{"t":"Being loved is a need of the fitrah","a":1279,"b":1591},{"t":"Case study: the girl with the flower in her hair","a":1591,"b":1952},{"t":"\"Isn't this too much?\"","a":1952,"b":2133},{"t":"Effect one: the child adopts the lifestyle of the beloved","a":2133,"b":2558},{"t":"Effect two: willing obedience","a":2558,"b":2864},{"t":"Effect three: resilience under hardship","a":2864,"b":3174},{"t":"Effects four and five: limited deviation, and a transmissible sunnah","a":3174,"b":3538},{"t":"What spoils love: manipulation, and love without respect","a":3538,"b":3784},{"t":"The objection: conviction or affection?","a":3784,"b":3967},{"t":"Technique one: say it out loud","a":3967,"b":4334},{"t":"Techniques two to six: the body, the pen and the face","a":4334,"b":4762},{"t":"Technique seven: play as a child — and the sentence he ran out of time for","a":4762,"b":4885}],"takeaways":["Loving your child and your child feeling loved are two different facts, and only the second one does anything.","Every interaction should carry two messages: love and karamah.","Being loved is a need Allah placed in the human constitution, not a weakness to be trained out.","Small children's self-centredness is a design feature, not a moral failing.","Children copy the person they admire, not the person they are near.","Authority by fear expires; authority by love outlives you — and parental authority is a finite magazine.","Love used as a lever stops working, because children can detect a transaction.","","Do not let the frequency of \"I love you\" fall as the conflicts rise.",""],"principles":["Loving them and their feeling loved are two different facts.","Every interaction: love and dignity.","Being loved is a need, so meeting it is duty.","Children copy whom they admire.","Love used as a lever stops being love.","Authority by fear expires; authority by love outlives you.","Say it out loud — that is what makes it hold.","Play as a child, not as a supervisor."],"nuggets":[{"q":"Did you feel intense love — or did you think: mommy is doing her job?","ts":1527,"note":"The sentence the whole lecture is built on. Everything else is an elaboration of it."},{"q":"I have to look at this from the lens of the child.","ts":1591,"note":""},{"q":"Imagine a child — every time my parents see me, their face lights up.","ts":1952,"note":"The cheapest instruction in the series and possibly the highest-yield."},{"q":"The little boy wants to resemble the beloved.","ts":2377,"note":"Why you trace a behaviour to the person the child loves, not the person the child fears."}],"practices":["Say it, in words, to each child by name. ✅ sahih — al-Kafi, bab i'lam al-akh bi'l-hubb, h.2. Not \"I love you guys.\" \"Abbas, I love you.\" \"Eliyya, I love you.\" The narration gives the reason: it makes the affection firmer. It is maintenance, not decoration. [67:08]","The morning hand on the head. ✅ 'Uddat al-Da'i p.87 — chainless, but specific: the Prophet (s) did this when he rose in the morning. It takes two seconds per child and it is the easiest Sunnaic practice in this lecture to install. [33:32]","Let your face do the work. ✅ Of the three faces — neutral, frowning, lit up — only one of them is free and also correct. It happens six or eight times a day per child. [31:32]","Greet before you assess. ✅ The whole flower-in-the-hair contrast turns on sequence: salaam, look, ask about the day — then the practical business. Not the reverse. [26:31–30:32]","Say a du'a for them out loud, in their hearing, as they leave. ✅ His own suggestion and a good one. [70:12]"],"questions":{"parent":["If Abbas were asked today — how do you know your dad loves you? — what would he actually say? Not what would be true; what would he say?","Which of my expressions of love are really expressions of duty? Which of them would a child recognise as love, and which as maintenance?","When did I last tell each child, in words, by name, that I love them? Is the honest answer a number of hours or a number of days?"],"spouse":["Which of our children currently feels most loved? Which feels least? Do we agree?","Between the two of us, who carries the warmth and who carries the standard? Is either child getting only one of them from both of us?","What did our own parents do that made us feel loved — and what did they do that they thought made us feel loved?"],"family":["What is something someone in this family did this week that made you feel happy?","What is your favourite way for someone to show you they love you? (Ask each person, including the parents. Write the answers down.)","Who is someone you really look up to? What is one thing about them you would like to be like?"]},"activities":{"abbas":["\"Who Do You Look Up To?\" (discussion prompt)","The Promise Ledger (character-building)","The Story of al-Aqra' (a story)","Three Faces (real-life challenge)","The Letter (character-building + bonding)"],"eliyya":["The Yes Cupboard (play-based learning)","Tag, With Everybody (play-based, bonding)","Good Morning, On the Head (Islamic manners, bonding)","\"I Missed You\" Words (emotional development)","The Spill Rule (Islamic manners)","The Lit-Up Face Game (bonding, emotional development)"]},"corrections":[{"claim":"The category of a fitri need","status":"✅ Strongly verified","note":"Uses it for the category, correctly. ⚠ al-Mizan reads la tabdil as fact, not prohibition; he does not overreach"},{"claim":"Love → willing following","status":"✅ Strongly verified","note":"al-Mizan and Majma' al-Bayan both supply the mechanism; Tabrisi: love is the willing of obedience. ⚠ The wilaya extension is his, in neither tafsir. ⚠ ittiba', not ta'a"},{"claim":"Three legacies; righteous child","status":"⚠ Moderately verified","note":"Bihar 71:257; Muslim 1631 sahih. ⚠ Child is third, not first; text says \"nothing follows him except\", not \"best legacy\""},{"claim":"Withhold a right → spend double later","status":"❌ NOT LOCATED","note":"Nahj hikam, Wasa'il on man' al-zakat, maxim corpus — all negative. Substitute: Nahj Hikmah 244"},{"claim":"\"Love children and have mercy on them\"","status":"⚠ Moderately verified","note":"al-Kafi 6:49 ch.35 h.3, majhul. ⚠ Promise-keeping clause omitted again, as in Part 2"},{"claim":"Akrimu awladakum… yughfar lakum","status":"⚠ Moderately verified","note":"Makarim al-Akhlaq 1:254 — chainless; Wasa'il 21:476; Bihar 101:95; Ibn Majah 3671 da'if. ✅ He keeps yughfar lakum"}],"counts":{"verses":2,"narrations":24,"audit":33}},{"n":4,"slug":"lecture-04-freedom-and-the-duties-of-fathers","title":"Freedom in the First Seven Years, and the Duties of Fathers","video":"N99YCY4lUK8","minutes":22,"thesis":"The third of the \"books\" — after love and (in the earlier sessions) the foundations — is freedom. Shaykh Usama's claim is that a small child's freedom is not a concession, a reward, or a risk to be managed: it is a need with a design behind it, comparable to food, placed in the child by Allah and scheduled to expire. Meet it in the first seven years and it is discharged; refuse it and it does not disappear — it resurfaces later as mischief, rebellion, concealment and an obedience that evaporates the moment you leave the room.","why":"","topics":[{"t":"Book three: freedom, and the seven things it produces","a":0,"b":61},{"t":"What happens when freedom is withheld","a":61,"b":182},{"t":"Why parents don't do it: the recap","a":182,"b":243},{"t":"The three duties of fathers","a":null,"b":null},{"t":"Redefining \"spoiled\"","a":672,"b":733},{"t":"\"Misusing freedom\", and the two limits","a":733,"b":794},{"t":"Karama: Islamic self-worth as the engine of emotional regulation","a":794,"b":916},{"t":"Freedom has an expiry date — and the muaddab claim","a":916,"b":1036},{"t":"Free at home, bounded outside","a":1036,"b":1097},{"t":"Older siblings, spacing, and conversation from seven","a":1097,"b":1219},{"t":"Favouritism","a":1219,"b":1281}],"takeaways":["Freedom in the first seven years is a need, not a permission.","The test that separates a limit from a preference: danger, or age-inappropriateness.","Spoiled = demanding what you don't need or what harms you, and insisting.","Honour comes before manners, in that order.","Dignity is intrinsic, not earned — and the verse for it is Q 17:70.","Fear-based authority does not survive your absence.","The child checks whether the permission is real.","Freedom is a household policy, not a maternal one — and the father has three jobs.","Design the house so that \"yes\" is cheap.","From seven, the tool is conversation — and the older child is a partner, not an obstacle."],"principles":["Freedom in years 0–7 is a need, not a permission — from Imam al-Sadiq (a), not from a verse.","A limit is danger or age-inappropriateness. Everything else is your preference. (A scholars' rubric, not a hadith.)","Spoiled = unneeded or harmful + insistence.","Honour first, manners second.","Authority built on fear ends at the doorway.","Design the house so \"yes\" is cheap.","Years 7–14 are your work, not your harvest.","Count what you give each child. They already have."],"nuggets":[{"q":"Freedom is a need that God hardwired this child to have during the first seven years. If that need isn't met, it's going to come back to bite us later.","ts":733,"note":"The thesis of the lecture in one sentence. ⚠ Just say \"the Imam said,\" not \"Allah said.\""},{"q":"My limits are narrower than the limits of the Ahlul Bayt.","ts":733,"note":"The most useful sentence in the talk, and the most quietly damning. ⚠ The rubric that follows is a scholars' distillation, not a narration."},{"q":"That's my limitation. That's not… whatever [the Ahlul Bayt] have determined as being dangerous.","ts":794,"note":"Every parent should be able to say this about at least one of their own rules."},{"q":"What being spoiled is, is: I'm asking for something that I don't need, or something that's harmful, and then I'm insisting on it.","ts":672,"note":"His own definition, and a genuinely good one."}],"practices":["Ask the two-limit question before every \"no.\" Is this dangerous? Is it wrong for her age? If it is neither, it is your convenience — and you may still say no, but say it as your preference, not as Islam. [12:13]","Let one harmless consequence teach, every day. Water in the rice; shoes on the wrong feet; the tower she built falling over. One a day is enough to build the habit in you. [01:01]","Say something that honours Abbas out loud, unconnected to performance. Not \"well done\" — \"I'm glad you're my son,\" \"I trust you with this.\" Akrimu awladakum comes before ahsinu adabahum, and the order is the instruction. [14:15]","The father's hour. When you come in, take both children for a set block so your wife is genuinely off duty — not \"helping,\" off duty. Name the time so it is checkable. [04:03–05:05]","Run the absence test on yourself once a day. Would they have done that if I had been out of the room? [03:02]"],"questions":{"parent":["In the last week, how many of my \"no\"s were about danger or age — and how many were about my convenience? Be specific; name three.","What does my face do when Eliyya makes a mess? What has she learned to read there?","What does Abbas do when I leave the room? Is what I have from him compliance or conscience?"],"spouse":["Are we actually agreed that the house will look different for the next three years — or has one of us agreed in principle and not in practice?","What will each of us say to the other on the day the water goes on the floor? Say it now, out loud, in advance.","Which of us undercut the other's decision most recently, and in front of whom?"],"family":["What is something everyone in this family is allowed to do at home that we do not do at other people's houses? Why is that fair?","What is a rule in this house that keeps someone safe? Can each of you name one?","What is a rule in this house that is just because Baba likes it that way? (Say one. Let them laugh.)"]},"activities":{"abbas":["The Two Limits Card (discussion + real-life challenge)","\"I Can't Do This Without You\" (discussion; the lecture's own instruction)","The Fairness Ledger (character-building; run it on yourself)","The Story of the Honey (a story, told as a story)","The Yes Room (real-life challenge, done with his hands)","What the Imam Actually Said (character-building; sourcing as a skill)"],"eliyya":["Twenty Minutes of Yes (play-based)","The Pouring Tray (play-based, natural consequences)","\"I Promised, So\" (emotional development)","Big Person, Small Person (Islamic manners, and *karama)*","Be a Child With Her (parent–child bonding)","Outside Is Different (Islamic manners)","The Salam Race (Islamic manners, bonding, and the case study's warning)"]},"corrections":[{"claim":"\"The child becomes muaddab — not that you make him so\" [15:16]","status":"❌ WRONG — strongly verified against","note":"No version uses Form V yata'addab. Extant forms are passive (yu'addab, al-Faqih 3:492) or imperative to the father (fa-addibhu bi-adabik, al-Kafi 6:47 h.2). Confirmed against Hobbollah's survey of all eight versions"},{"claim":"The second seven = becoming mannerly [00:00, 15:16]","status":"⚠ MEANING ALTERED","note":"h.3's second seven is yata'allamu al-kitab — learning to write. Only mursal versions mention ta'dib, and always with a parental agent"},{"claim":"Early freedom ⇒ later obedience [01:01, 15:16]","status":"⚠ MEANING ALTERED","note":"Both outcome-bearing narrations end in an explicit failure branch — fa-in aflaha wa illa… / fa-in qabila wa salaha wa illa…"},{"claim":"\"The freedom that Allah said to give\"; \"God hardwired\" [01:01, 12:13]","status":"❌ CATEGORY ERROR","note":"It is a hadith of Imam al-Sadiq (a), not Qur'an. No such verse exists"},{"claim":"\"The Ahl al-Bayt have said: danger + age-inappropriateness are the limits\" [12:13]","status":"❌ NOT LOCATED — do not attribute","note":"Deliberate absence-check, negative in Arabic and Persian. Contemporary systematisation; refines the index's \"four red lines\" entry. Content sound; attribution not"},{"claim":"\"Honour your children… then make sure they're mannerly\" [14:15]","status":"⚠ MODERATELY VERIFIED","note":"Akrimu awladakum wa ahsinu adabahum yughfar lakum — Makarim 1:254; Wasa'il 21:476 h.27611; Bihar 101:95; Ibn Majah 3671. Chainless (Shia) / da'if — al-Busiri (Sunni). Rendered accurately; forgiveness clause dropped"}],"counts":{"verses":2,"narrations":7,"audit":26}},{"n":5,"slug":"lecture-05-last-objections-order-and-the-boisterous-child","title":"The Last Objections: Order, the Divided Household, and the Boisterous Child","video":"iRi_nYyd2-Y","minutes":57,"thesis":"This is the session where the Shaykh closes out his defence of the first seven years. Parts 3 and 4 argued that a child under seven has an Islamic right to freedom — to play, to move, to make a mess, to take things apart. Part 5 answers the last six objections real parents raise against that, and in answering the fourth of them he arrives at the lecture's genuinely original contribution: a redefinition of what \"order\" means in Islam.","why":"This lecture is the bridge between a principle and a household. It is easy to accept in the abstract that a four-year-old should be free; it is hard when your mother-in-law is watching, when you rent, when your husband disagrees, and when the carpet is new. Part 5 is about that gap. Its best sentence is not a hadith at all — it is the diagnostic question at [49:43]: \"the psychological effects on t","topics":[{"t":"Who pays when a principle costs something","a":5,"b":126},{"t":"What tarbiyah cannot do: guidance belongs to Allah","a":126,"b":248},{"t":"The three things already built: modelling, interaction, felt love","a":248,"b":368},{"t":"The ledger: seven benefits, eight harms","a":368,"b":612},{"t":"The remaining objections, named","a":795,"b":1041},{"t":"Objection 1: \"What will people say?\"","a":1041,"b":1224},{"t":"Objection 2: \"We live in an apartment\"","a":1224,"b":1466},{"t":"Objection 3: \"My spouse is not on board\"","a":1466,"b":1889},{"t":"Objection 4: \"When do they learn structure and order?\"","a":2130,"b":2558},{"t":"Other people's things, talqin, and the guest exception","a":2558,"b":2739},{"t":"Two questions from the room","a":2739,"b":2861},{"t":"The modern lifestyle, and the wall [47:41–51:45]","a":2861,"b":3105},{"t":"Objection 5: \"Isn't this israf?\"","a":3105,"b":3288},{"t":"Objection 6: \"They'll get sick\"","a":3288,"b":3360}],"takeaways":["If a principle costs something, the parent pays — not the child.","Order (nazm) means everything in its proper place, not everything tidy.","A child under seven who has scattered the pots is not disordered — he is on schedule.","Boisterousness in a small child is recommended, and forbearance is what it produces.","Guidance is Allah's; the method does not manufacture belief.","Never win the argument at the price of the marriage.","Persuade a reluctant spouse with questions, not verdicts.","Stopping a child is fine — as the exception, not the default.","When a wall gets painted, two things happen — and only one of them is visible.","Sacrifice is the mechanism when a spouse is unwilling."],"principles":["If somebody must sacrifice, the parent sacrifices.","Nazm = everything in its proper place. The proper place of a small child is at play.","Boisterousness now is forbearance later — recommended, not tolerated.","The road is yours; the arrival is Allah's.","Do not win the argument at the cost of the marriage. Salah dhat baynikum outweighs general prayer and fasting.","Stopping a child is fine as the exception; it is corrosive as the default.","When the wall and the soul collide, only one of them is an amanah."],"nuggets":[{"q":"If setting my children free — or following some other Islamic principle — meant somebody has to sacrifice, should it be the parents who sacrifice, or the child?","ts":66,"note":"The question the whole lecture is built on, and the one he lets the room answer."},{"q":"The spirit of being organised is when everything is in its proper place.","ts":2251,"note":"The definition. ⚠ And note that Imam Ali's own phrase — nazm amrikum, the order of your affairs — proves it better than the dictionary does."},{"q":"If a three-year-old has scattered pots and pans all over — they are actually organised. Because at this stage they're supposed to be free.","ts":2313,"note":"The sentence that dissolves the objection rather than out-arguing it."},{"q":"It is good for the child to be lively, full of motion when they're young, in order that the child be forbearing.","ts":2435,"note":"✅ al-Kafi 6:51, ch.37 h.2 — Imam al-Kazim (a). majhul, and worth saying so. ❌ The clause he adds after it is his own."}],"practices":["Run the sacrifice test before you enforce anything. Whose comfort does this rule protect? If the answer is yours, you may still enforce it — but you now know what you are doing. [01:06]","One breath before you speak about a mess. The wall is already painted; your reaction is not yet made. [49:43]","Say the nazm sentence to yourself. \"Everything in its proper place.\" Eliyya on the floor with the pots is in her proper place. [38:33]","Give Abbas at least one long stretch of real movement. Outdoors if at all possible. Not a scheduled activity — unstructured, self-directed, boisterous. This is the 'arama narration in practice.","Make one thing they are doing feel loved rather than tolerated. Sit down in the play for five minutes rather than supervising it from the doorway. \"Whoever has a child with him, let him make himself a child for him\" (al-Faqih 3:483 h.4707)."],"questions":{"parent":["When my child makes a mess, what is the first thing I mourn — and what does that tell me?","Of the rules I enforce at home, how many exist to protect the child and how many to protect a surface, a schedule, or my standing with visitors?","Which of the eight harms at [09:10–10:12] can I already see in myself, from my own upbringing?"],"spouse":["Are we operating from the same set of facts about how children should be raised — or from two sets we have never compared? [26:27]","Where do we currently give the children different rulings, and which one of us do they go to first?","What is each of us paying for the children's freedom right now, and is it fairly divided?"],"family":["What does it mean for something to be \"in its proper place\"? Where does a four-year-old belong? Where does a seven-year-old belong?","If Allah gave every one of us a job, what is the job of a seven-year-old? What is the job of a father?","Imam Ali (a) said: make yourself the measure between you and others. What does that mean when we are at someone else's house?"]},"activities":{"abbas":["The Proper Place Hunt (discussion prompt + real-life challenge)","The Story of the Boisterous Boy (story)","The Measure (character-building exercise)","The Repair Shop (real-life challenge, and the ownership transition)","The Guest Rule (discussion + rehearsal)"],"eliyya":["The Yes Box (play-based learning)","Water Day (play-based, and the *israf answer in practice)*","Sound-Effect Tidy-Up (parent–child bonding)","\"Is It Hurt, or Is It Just Different?\" (emotional development)","Salaam and Sorry (Islamic manners)","Outside, Whatever the Weather (play-based, immune, bonding)"]},"corrections":[{"claim":"People of Paradise credit Allah for their guidance","status":"✅ Strongly verified — correct","note":"Well chosen, against religious condescension. ⚠ al-Mizan not consulted on this verse; no position reported"},{"claim":"Zakariyya's household \"vying in good\"","status":"✅ Strongly verified — correct, lightly embellished","note":"al-Mizan: the plural pronoun is «بيت زكريا», and the favour was granted because they hastened. ⚠ Yusari'una fi'l-khayrat is racing in good, not against each other"},{"claim":"\"Allah says don't do israf\" (child spilling water/food)","status":"⚠ Moderately verified — correct conclusion, under-argued","note":"Q 7:31 / 17:26–27 are the loci. Firmer route: a pre-baligh child is not mukallaf, so israf does not attach to the child at all"},{"claim":"Lively child → forbearing adult","status":"⚠ Moderately verified — correct","note":"al-Kafi 6:51, Kitab al-'Aqiqa ch.37 h.2, Imam al-Kazim (a). al-Majlisi: majhul; Behbudi excluded. ✅ His \"lively, full of motion\" beats thaqalayn's English"},{"claim":"\"…and be concerned if a child sits still and complies\"","status":"❌ Not in the text — his inference","note":"Not in the retrieved al-Kafi Arabic. Defensible as inference; do not quote as the Imam's words"},{"claim":"Imam Ali's will: taqwa + nazm amrikum, \"two things\"","status":"⚠ Strongly verified text — but the count is wrong","note":"Nahj al-Balagha Letter 47. Chainless. Three items; the third, salah dhat baynikum, is the one the Imam then expounds — and the one this lecture most needed"}],"counts":{"verses":4,"narrations":13,"audit":30}},{"n":6,"slug":"lecture-06-the-gentle-art-of-setting-children-free","title":"The Gentle Art of Setting Children Free","video":"q3oqrYtHXmE","minutes":37,"thesis":"A child under seven experiences freedom as love. Therefore the parent's task in these years is not to win the daily contest of wills but to engineer the contest out of existence — to arrange the house, the possessions, the schedule and the parent's own nervous system so that the number of moments requiring the word \"no\" collapses. Shaykh Usama calls this the gentle art of setting our children free, and he is explicit that it is an art of de-escalation before it is anything else:","why":"Every previous lecture in this series argued that the first seven years belong to love, play and freedom. This is the first one that tells a parent what to buy, where to sit, and what to do with his hands in order to make that possible. Its centre of gravity is a claim that sounds soft and is not: most conflict with a small child is an artefact of the adult's arrangements, not of the child's chara","topics":[{"t":"The gentle art defined: de-escalation before technique","a":0,"b":62},{"t":"Why freedom reads as love to a child under seven","a":62,"b":123},{"t":"The five conditions of the warm home, recapped","a":305,"b":613},{"t":"How a servant proves love: Q 3:31","a":551,"b":613},{"t":"Two ways to deepen the relationship: Qur'an daily, and the Imam","a":613,"b":673},{"t":"The Samarra story","a":673,"b":1037},{"t":"The second preliminary: tarbiyah costs the parent","a":1037,"b":1219},{"t":"Why was this family chosen? Q 21:90","a":1219,"b":1342},{"t":"Shahid Mehdi Zeinoddin, and what sacrifice looks like at home","a":1342,"b":1584},{"t":"\"Don't look only at the finished product\": Zeinoddin at seven and at fourteen","a":1584,"b":1644},{"t":"No habituation to shouting, no prolonged silent treatment","a":1644,"b":1765},{"t":"Policy one: buy the house, the rug and the cups with tarbiyah in mind","a":1765,"b":1947},{"t":"Policy two: participation and guidance","a":1947,"b":2008},{"t":"Worked example one: the turbah","a":2008,"b":2130},{"t":"Worked example two: water play","a":2130,"b":2192},{"t":"Close and hand-off","a":2192,"b":2240}],"takeaways":["A child under seven experiences freedom as love.","Most conflict with a small child is an artefact of the adult's arrangements.","Islamic tarbiyah requires the parent to be uncomfortable, and adults duck that by pretending the problem went away.","Q 21:90: the household of Zakariyya was favoured because they raced one another to good deeds.","Q 3:31: a claimed love is tested by what you follow.","\"Participation and guidance\" — be a fellow playmate who redirects, not a sentry who forbids.","Buy the rug, the cups and — if you can — the house with tarbiyah in mind.","Don't habituate a child to shouting, and don't prolong the silent treatment.","Do not read a seven-year-old's behaviour as a verdict.","Sacrifice is domestic before it is heroic."],"principles":["Under seven, freedom is how love is received.","Count the \"no\"s before improving the \"no\"s.","Every object either generates prohibitions or absorbs accidents.","Participate and redirect; do not stand outside and forbid.","Provide the thing he wants on your schedule rather than tolerating it on his.","Displeasure yes; prolonging no.","Favour fell on a household that raced to good.","If nothing became less comfortable for you, nothing changed.","Method is obligatory; outcome is Allah's."],"nuggets":[{"q":"The gentle art of setting our children free.","ts":0,"note":"The title, and the whole thesis: an art of subtraction before it is an art of technique."},{"q":"These are fewer areas where we have to go bone on bone with the children.","ts":0,"note":""},{"q":"The child feels: those who set me free, those who let me do what I want — they're doing it because they love me. In the first seven years, that's how I receive love.","ts":62,"note":"The sentence the rest of the lecture is built on."},{"q":"If we're able to succeed in this one area — our children feel my parents really, really love me — a lot of the heavy lifting has been done already.","ts":62,"note":""}],"practices":["Count your \"no\"s to Eliyya. Not to feel guilty — to sort them. Danger, or furniture? One tally sheet on the fridge for one week is enough to change your buying decisions for a decade. [00:00, 29:25]","Say yes out loud when you can. A child under seven reads permission as love [01:02]. When the answer is genuinely yes, make it audible and warm rather than distracted and grudging. The tone is the message.","Play inside the game, not outside it. When Eliyya's play drifts somewhere unsafe, use playmate grammar — \"let's take these over to the rug\" — rather than sentry grammar — \"stop, don't.\" Same outcome, no confrontation. [32:27] Warrant: «مَنْ كَانَ عِنْدَهُ صَبِيٌّ فَلْيَتَصَابَ لَهُ» (al-Faqih 3:483 h.4707).","Keep displeasure short. If you withdraw warmth, restore it fast. The narration's own limit is \"and do not prolong it\" ('Uddat al-Da'i p.89 → Bihar 101:99 — weak chain, real wording). Thirty silent minutes is the exact thing it warns against. [28:25]","A little Qur'an, where they can see you. Four minutes with the mushaf, attending to meaning. [11:13] The children learn the habit from the sight of it, not from being told about it."],"questions":{"parent":["In the last week, how many of my prohibitions to Eliyya protected her, and how many protected an object?","What did I buy in the last two years that I now police daily?","When I am displeased with Abbas, how long does it last — and who decides when it ends?"],"spouse":["Where do you and I disagree about what the children are allowed to do? Name one case each.","What in this house do you find yourself defending from the children all day?","If we could change one thing about this home to make it easier to say yes, what would you change?"],"family":["What does it mean that Allah blessed one family because they raced each other to do good? (Q 21:90)","What is one good thing this family could compete at this week?","Who in this house is best at noticing when someone needs help — and how do they do it?"]},"activities":{"abbas":["The Race to Good (household competition, from Q 21:90)","The Boots (story + discussion)","Little Sister's Yes (character-building)","Verse Detective: what does love look like? (discussion, Q 3:31)","The House Walk (real-life challenge)"],"eliyya":["Her Own Turbah (play-based, Islamic manners)","Water Day (play-based, sensory)","The Yes Zone (freedom with a boundary)","Waiting to Eat Together (emotional development, bonding)","Kind Hands (Islamic manners, gentleness)","Fast Hands for Good (Eliyya's version of the Race to Good)"]},"corrections":[{"claim":"Q 3:31 — \"if you love Allah, follow me… Allah will love you\"","status":"✅ Strongly verified","note":"Paraphrase accurate. al-Mizan: love entails khudu' and taslim. ⚠ ittiba' = following, a stronger word than \"obey\"; ⚠ the Najran sabab (Majma' al-Bayan) would have strengthened him"},{"claim":"\"The wife wasn't able to have children when she was young\"","status":"⚠ Loose","note":"al-Mizan: «جعلها شابة ولودا بعدما كانت عاقراً» — fertility restored in old age; 19:5 calls her 'aqir without reference to youth"},{"claim":"Allah's mercy for the intensity of love for one's child","status":"⚠ Located — meaning shifted","note":"al-Kafi 6:50 ch.35 h.5; hasan with mursal tail. Mercy attaches to the parent's love, not to the child's feeling loved"},{"claim":"7-7-7 stages, applied to Zeinoddin's childhood","status":"✅ / ❌ Split verdict","note":"Stage division: al-Kafi 6:47 h.3, muwaththaq / Behbudi sahih. The naughty→mannerly causation is not located; and both outcome-bearing versions carry an explicit failure branch he omits"},{"claim":"No habituation to shouting / prolonged silent treatment","status":"⚠ Under-cited","note":"A real narration exists — 'Uddat al-Da'i p.89 → Bihar 101:99, «لا تضربه، واهجره ولا تطل» — but with an anonymous narrator, six centuries late"},{"claim":"\"That scarring on their heart\"","status":"❌ Not located — do not attribute","note":"The speaker's own psychological language"}],"counts":{"verses":2,"narrations":13,"audit":36}},{"n":7,"slug":"lecture-07-setting-children-free-and-red-lines","title":"Setting Children Free: The Practice of Freedom, and the Two Red Lines","video":"2oXsXwPtZj8","minutes":66,"thesis":"Freedom in the first seven years is not the absence of parenting. It is a method, and it has a technique — one that can be described, taught, rehearsed and got wrong. Almost everything a parent instinctively does to control a small child, Shaykh Usama argues, spends a resource the parent will need far more urgently at fourteen:","why":"Parts 1 and 2 established why and what. Parts 4–6 established the stages and the tone. Part 7 is the first lecture that tells a parent what to actually do on Tuesday afternoon when a three-year-old is drawing on a rented wall. Its practical yield is high and its citation density is low — and those two facts are related. The strongest single sentence available on this exact subject, al-Kafi 6:50 ch","topics":[{"t":"Mother's Day, the ranks of motherhood, and the intention behind wanting a child","a":0,"b":120},{"t":"The reward promised, and the hadith that does not promise it","a":120,"b":182},{"t":"Tarbiyah as an inner change; the 'arif who laughed","a":182,"b":307},{"t":"The premise restated: intense love, and freedom as its form","a":307,"b":430},{"t":"The house, the rug, the clutter, and the silver bullets","a":430,"b":551},{"t":"The two roles: active participant, and playmate","a":551,"b":612},{"t":"Domain one: water play, and the two baths","a":612,"b":1035},{"t":"Domain two: cabinets and closets, and the lock the child must not see","a":1035,"b":1156},{"t":"Domain three: drawing on the walls — psychological bruising against a bucket of paint","a":1156,"b":1340},{"t":"Domain four: food, mess, and the cost of extra time","a":1340,"b":1461},{"t":"Domain five: books, ripping, and manufacturing a reader","a":1461,"b":1583},{"t":"Sacred books: how a child learns the Qur'an is different","a":1583,"b":1944},{"t":"Domain six: gatherings — four variables and a narration","a":1944,"b":2308},{"t":"Managing the child's palate, and the Cheetos evening","a":2308,"b":2737},{"t":"Red line one: dangerous behaviour, and four ways to prevent it","a":2737,"b":3163},{"t":"The escalation ladder, and the embrace afterwards","a":3163,"b":3404},{"t":"Red line two: inappropriate behaviour, and what makes it different","a":3404,"b":3586},{"t":"Step one: detective work, and the fitrah as a diagnostic","a":3586,"b":3828},{"t":"Taghaful, distraction, and the story with a hero","a":3828,"b":3949}],"takeaways":["Anger is ammunition with a fixed magazine — spend it accordingly.","Buy the cheaper rug.","Lock the cabinet when the child is not in the room.","The child is here to make you.","The parent's visible enthusiasm is the intervention.","Prepare the bath before the child enters the room.","Distraction is not a bribe.","After you have been stern, get the fear back out.","When a small child does something ugly, investigate before you correct.","A short visit counts."],"principles":["Anger is ammunition. Save it for knives, not rugs. [08:10]","Engineer the yes; the parent's work happens in advance and out of sight. [18:16]","Dangerous / inappropriate / merely inconvenient — only two are red lines. [56:44]","Investigate before you correct; the fitrah means it was imported. [59:46]","After sternness, always the embrace. [55:44]","A short visit counts. [35:26]","The child is here to make you. [05:07]"],"nuggets":[{"q":"I can use it up now by correcting, by fixing — but then when I need it later, when the child is 14, 15, 16, 17, I won't be able to lean on it, because I burned up my chances by screaming and shouting when the child was young.","ts":672,"note":"The thesis of the lecture in one sentence."},{"q":"The child is here to make you.","ts":307,"note":"The 'arif's reply, after he had finished laughing."},{"q":"Some parents will lock that cabinet in front of the child. … If you do it when the child's not there, and I just come in and some of the doors are locked — that was just some of the doors.","ts":1096,"note":"The most psychologically precise observation in the lecture, and it is free."},{"q":"How valuable is it to us that our child doesn't suffer psychological bruising? … It's definitely worth it to pay that price.","ts":1278,"note":"On repainting a rented wall."}],"practices":["Count your silver bullets. Before raising your voice, name what the round is being spent on. If the answer is an object, put it back in the magazine. [08:10, 52:43]","Run rung one first, silently. The child is heading for the oven; get on your knees and be a horse. No \"no,\" no negotiation, no cost. [53:43]","Say one du'a out loud, in front of them. Not silently. The best single instruction in the six-point passage, whoever said it. [28:24]","Handle the Qur'an in front of them the way Mahmud's father did — both hands, wudu when you can, a kiss. Say nothing about it. They are watching. [30:24]","Give the meal its real length. Whatever you have budgeted for Eliyya's dinner, add ten minutes at the front, not at the back. [23:21]"],"questions":{"parent":["How many silver bullets did I spend this week, and how many of them were spent on objects? [08:10]","Which of the two mothers in the bath case study is closer to how I handle the friction points in our house — and is the gap a gap in kindness, or a gap in preparation? [12:13–16:14]","When I say no to Abbas or Eliyya, is it because the thing is dangerous, because it is inappropriate, or because it is inconvenient to me? Honestly — what is the ratio? [56:44]"],"spouse":["Which of us is the one who says no first, and is that a difference in judgement or a difference in tolerance for mess?","Can we agree, now and in cold blood, that finding the source of a behaviour is not the same as assigning blame? What will we say to each other when the source turns out to be one of us? [62:48]","Which three objects in this house are we willing to lose in exchange for not shouting for the next four years? [08:10]"],"family":["What is the best game we have played together in this house, and when did we last play it?","What are the rules in our home that exist for safety, and which ones exist just because they are the rules? Can the children tell the difference?","If we could turn one room into a place where nothing can be broken, which room would it be, and what would we do there?"]},"activities":{"abbas":["The Real Knife (real-life challenge)","The Silver Bullet Jar (character-building, and it is aimed at you as much as him)","Detective Week (discussion + real-life challenge)","The Story of the Birds (story)","The Repair, Not the Blame (character-building)"],"eliyya":["Bath Like Fatima's (play-based learning)","The Open Cupboard (play-based, emotional development)","Colour, Water, Outside (play-based)","Her Own Small Qur'an (Islamic manners)","Two Plates, One Face (emotional development, bonding)","The Twenty-Minute Visit (parent-child bonding, Islamic manners)"]},"corrections":[{"claim":"Two birds; \"better than my kingdom\" [01:00]","status":"⚠ Moderately verified","note":"al-Majlisi, Hayat al-Qulub vol.1, \"An account of Sulayman.\" Chainless qisas. Actor is Prophet Sulayman (a), not Muhammad (s). One male bird, not two; \"now that we have become old\" is dropped"},{"claim":"Man qaddama awladan [02:00]","status":"❌ Failed — meaning inverted","note":"Thawab al-A'mal p.178 → Bihar 82, in ch. Ajr al-Masa'ib; qaddama = children who died first; parallel specifies children below the age of accountability. Weak chain ('Amr b. Shimr ← Jabir al-Ju'fi). Third occurrence in the series. Substitute: al-Kafi 6:6 h.10 (hasan)"},{"claim":"Children are an amanah [05:07]","status":"⚠ Homiletic","note":"Absent from al-Mizan on 4:58, where amanat is broadened to knowledge and true understanding — not to children. Defensible preaching, not exegesis"},{"claim":"\"Al-hubbu asasi — love is the foundation of my way\" [06:08]","status":"❌ Not located — do not attribute","note":"No Shia or Sunni source with this wording. Nearest is a chainless Sufi list. Substitutes: al-Kafi 2:125 h.5 (hasan ka'l-sahih); al-Kafi vol.8 «وهل الدين إلا الحب»; ⭐ al-Kafi 6:50 h.5 (hasan)"},{"claim":"Khamenei: six-point upbringing list [27:24]","status":"⚠ Not verified","note":"Nothing on english.khamenei.ir, leader.ir, or the Persian tarbiyat fish indices. Third unsourced Khamenei attribution. ⚠ Report as unreachable archive: both fish indices are robots-blocked and khamenei.ir/leader.ir went 403 at the egress proxy mid-project"},{"claim":"Nothing more hated by Iblis than believers visiting [33:25]","status":"⚠ Moderately verified","note":"al-Kafi 2:188; al-Wafi 5:651; Wasa'il 16:347; Bihar 60:258. Imam al-Kazim (a). Chain Muhammad b. Sulayman ← Muhammad b. Mahfuz, likely weak; no grading published. ⚠ \"breaks Iblis's back\" is not in the text — the verb is ankā, \"wounds.\" ✅ Better sourced than he claimed"}],"counts":{"verses":3,"narrations":11,"audit":21}},{"n":8,"slug":"lecture-08-repairing-the-first-seven-years","title":"Repairing the First Seven Years: Karamah, Freedom After Seven, and Play as a Need","video":"CiglxUCR6CE","minutes":59,"thesis":"Tarbiyah has no closing date. If the first seven years were mishandled — if the child was controlled instead of set free — the damage is real, it is describable, and it is repairable, by a different route for each age band. And the repair runs on two things the tradition names explicitly: love felt intensely, and dignity felt intrinsically (karamah). Then, having closed the file on freedom, the Shaykh opens a new one: physical play with your children is not a concession you make to them, it is a need you owe them — and he grounds that on the single most vivid image in the Prophetic record of an adult with a child.","why":"Parts 6 and 7 taught freedom to parents of small children. Part 8 is for everyone whose small children are not small any more. Its practical yield is a rule of order: you cannot instruct a child who does not feel loved, and you cannot ask a teenager for taqwa before he feels he is worth guarding. ⚠ That last formulation — karamah is a prerequisite to taqwa — the Shaykh takes from a video of Shaykh","topics":[{"t":"Do not carry resentment toward your own parents","a":0,"b":245},{"t":"Making the dead partners in this, and the Prophet (s) at the fresh grave","a":245,"b":367},{"t":"\"Do not say they are dead\": 2:154, 3:169, and the parent as shahid","a":367,"b":607},{"t":"The question, and the three-branch triage","a":607,"b":729},{"t":"Branch one: the child still under seven","a":729,"b":1215},{"t":"Branch two: past seven, the pre-teen","a":1215,"b":1519},{"t":"Branch three: the teenager, and karamah","a":1519,"b":2371},{"t":"Does freedom end at seven?","a":2371,"b":2738},{"t":"The two things over-control destroys","a":2738,"b":2982},{"t":"A new book: physical play is a need","a":2982,"b":3531}],"takeaways":["It is not too late — but the route depends on the age.","Freedom was never the point. Feeling intensely loved was the point.","The repair makes things worse before it makes them better, and that is the repair working.","\"We helped build the monster.\"","Allah does not ask less of you than you can give — He asks exactly what you can give.","For a teenager, dignity comes before piety.","Dignity is intrinsic, not earned — and Q 17:70 says so.","Arrogance is the counterfeit of self-worth, not an excess of it.","Freedom does not end at seven; only the age-inappropriate freedoms do — and most of them end by themselves.","Play is a need — the Prophet (s) used the word."],"principles":["There is no closing date on tarbiyah; there are only different routes.","Freedom was the means; feeling loved was the end — and means are substitutable.","The repair makes the symptoms louder before it makes them quieter.","You helped build it. That is the only sustainable source of patience.","Allah asks exactly what you can give.","Dignity precedes piety.","Dignity is intrinsic, so it cannot be earned — and therefore cannot be lost.","Arrogance is a deficiency of karamah, not an excess of it.","Nothing ends at seven except the freedoms that no longer fit.","Play is a need. The Prophet (s) used the word."],"nuggets":[{"q":"Two light rak'ahs — things that you think are nothing — this is more beloved to the person in this grave than [the remainder of] your world.","ts":305,"note":"✅ Silsila Sahiha 1388, sahih bi-majmu' turuqih. The best-sourced sentence in the lecture, and he cited it to nobody."},{"q":"My son made me his mount, and I disliked to hurry him until he had fulfilled his need.","ts":3286,"note":"✅ Sunan al-Nasa'i 1141, sahih. The word in the Prophet's mouth is hajah — need. This is the whole argument for play, in one clause, in the source."},{"q":"We helped build the monster.","ts":1033,"note":"The most honest sentence in the lecture, and the only durable foundation for patience."},{"q":"The child is so used to sitting there and being obedient… I'm setting them free now, and the child doesn't even want it any more.","ts":789,"note":"What suppression actually looks like from the inside. Nobody warns parents about this."}],"practices":["Two rak'ahs of nafilah, deliberately, thinking of the narration. Not as a spiritual exercise — as an act of arithmetic. The man one day into his grave would trade the remainder of your world for them. [04:05] ✅ Silsila Sahiha 1388.","Say each child's name well, at least once, on purpose. The first checkpoint of dignity [35:28]. Notice the difference between the voice you use for \"Abbas, come here\" and the voice you use for a guest's name, and close the gap.","Convert one order into a request. Every day, catch yourself mid-command and rebuild it: \"I need you to…\" instead of \"go and…\" [36:29]. This is the cheapest single change in the lecture and it costs four seconds.","Keep the promises. The half of ahibbu al-sibyan that gets dropped: «وَإِذَا وَعَدْتُمُوهُمْ شَيْئًا فَفُوا لَهُمْ». If you cannot be certain, do not say it. ✅ al-Kafi 6:49–50 ch.35 h.3.","Get on the floor once. Ten minutes of physical play, initiated by you, with your body involved. ✅ Nasa'i 1141 — the Prophet (s) called it the child's need."],"questions":{"parent":["Which of my three children-shaped regrets is actually about me — my temperament, my week, my father — rather than about the child? [17:13]","When did I last feel my affection drop because a child had become difficult? What did I do with the drop? [22:15]","If I am honest, which freedoms am I withholding for my convenience and calling them safety? [12:09]"],"spouse":["Where do the two of us disagree about how much freedom our children should have — and which of us is arguing from evidence and which from temperament?","Which of us is the \"crack down at seven\" instinct? Which is the \"let it run\" instinct? How do we want that to resolve when it matters? [40:31]","Which of the love-methods are we actually running this month, and which have quietly lapsed? [21:15]"],"family":["What is something you are allowed to do now that you were not allowed to do when you were smaller? Why do you think that changed?","What is something you were allowed to do that you do not want to do any more? (This is [43:35] turned into a question a child can answer.)","If Allah honoured every child of Adam — what does that mean about the person you like least in your class?"]},"activities":{"abbas":["\"Is it in a book?\" (discussion prompt + character-building)","The Gold Bar, and then the Correction (story + discussion)","The Promise Ledger (character-building, and it works on the parent)","Learning by Consequence: the Supervised Mistake (real-life challenge)","The Arrogance Detective (discussion + character-building)","Two Verses, Ten Verses (discussion, and a real tafsir skill)"],"eliyya":["The Camel (play-based learning, parent-child bonding)","\"You Decide\" (emotional development, dignity)","The Promise Game (Islamic manners, trust-building)","Salaam to the Small (Islamic manners, bonding)","Big Feelings, Small Words (emotional development)","The Freedom Restored (play-based, the branch-one repair in miniature)"]},"corrections":[{"claim":"Imam al-Sajjad's (a) du'a for parents: reward what they got right, forgive what they got wrong","status":"✅ Strongly verified","note":"al-Sahifa al-Sajjadiyya, Supplication 24. Stronger than he claimed — it has the child formally waive the claim. ⚠ The lines he recited are Q 17:24 + Q 71:28, not the Sahifa"},{"claim":"The Prophet (s) at the fresh grave: two light rak'ahs","status":"✅ Strongly verified","note":"Abu Hurayra; Ibn al-Mubarak al-Zuhd 31, Ibn Abi Shayba 7715, al-Tabarani al-Awsat 920. al-Albani: sahih bi-majmu' turuqih (Silsila Sahiha 1388). ⚠ \"the remainder of your world\"; the wish is the deceased's own"},{"claim":"Q 2:154 is not set in a military context; 3:169 is","status":"✅ Contextual claim strongly verified / ⚠ attribution needs further verification","note":"al-Mizan: 3:169 = «تتمة الآيات النازلة في خصوص غزوة أُحد»; 2:154 = five verses of one non-military siyaq, and he rejects restriction to Badr. khamenei.ir unreachable — an unreachable archive, not a completed negative"},{"claim":"\"Alive\" extends to parents and teachers of tarbiyah","status":"⚠ Homiletic extension","note":"al-Mizan generalises who shares the barzakh life, not who counts as killed in the way of Allah. The promised \"conditions\" [08:07] were never given"},{"claim":"Children as elite soldiers of Imam Mahdi (a)","status":"⚠ Moderately verified / homiletic","note":"Nearest text: al-Nu'mani, al-Ghayba bab 20 h.10 → Bihar 52:334, «أَصْحَابَ الْقَائِمِ شَبَابٌ»; weak chain, no grading"},{"claim":"The three-branch remediation scheme (under 7 / pre-teen / teenager)","status":"⚠ Contemporary systematisation","note":"No classical text sets out this triage. Consistent with al-Walad al-Salih (Jam'iyyat al-Ma'arif). Right register; keep it"}],"counts":{"verses":4,"narrations":24,"audit":38}},{"n":9,"slug":"lecture-09-why-parents-dont-play-nine-barriers","title":"Why Parents Don't Play: The Nine Barriers to Active Play","video":"1MoAzcfMEzY","minutes":41,"thesis":"Part 8 established that the Ahlul Bayt (a) played active physical games with children and commanded parents to let children play. Part 9 asks the only question that matters next: if this works, why does almost nobody do it? The lecture is a systematic diagnosis of parental resistance — nine reasons a sincere, practising, loving parent still does not get down on the floor and play. And the diagnosis is aimed inward:","why":"This is the most practically actionable lecture in the series so far, and also the one a parent is most likely to repeat inaccurately. Its best moments are genuinely first-rate: the lazy-eye analogy [25:32] is the single best-chosen image in sixteen lectures — amblyopia really is a sensitive-period condition, treated by patching the strong eye, and it carries exactly the moral he wants. The \"who's","topics":[{"t":"Where we are, and the three things already established","a":0,"b":374},{"t":"Barrier 1: not knowing it is a need — the benefits of active play","a":374,"b":677},{"t":"Barrier 2: the wrong philosophy of play, and the screen as substitute","a":677,"b":920},{"t":"Barrier 3: the game is meaningless to the adult","a":982,"b":1165},{"t":"Barrier 4: no running list of games","a":1165,"b":1226},{"t":"Barrier 5: the unmotivated parent, and the two traits","a":1226,"b":1349},{"t":"Barrier 6: the modern lifestyle, in five parts","a":1349,"b":2081},{"t":"Barrier 7: play takes time, and the two parents who fail","a":2081,"b":2202},{"t":"Barrier 8: too few children, or gaps too wide","a":2202,"b":2323},{"t":"Barrier 9: the child who no longer wants to play","a":2323,"b":2383}],"takeaways":["Play is a need, not a want — and the reclassification is the whole intervention.","The soundest text in this whole territory is al-Kafi 6:47, h.3 — and it carries a failure branch nobody quotes.","He gave the right meaning of the \"two traits\" narration and the wrong Imam.","Two showpiece stories in this lecture are unsourced. Do not repeat them as narrations.","\"Non-renewable energy\" is his own coinage and, read literally, it is false — but the thing it points at is real.","The best-supported claim in the lecture got one sentence: outdoor play measurably changes a small child's immune regulation.","Screens and play compete for hours; the claim that screens destroy the appetite for play is not established.","Some misbehaviour is a movement deficit wearing a discipline costume.","The lazy eye is the right model for early intervention — patch the good eye, and the window narrows rather than closes.","The screen is often the peace treaty, not the seducer."],"principles":["Play is a need, not a want.","The parent is usually the obstacle.","The unmotivated parent suppresses play, not merely omits it.","Misbehaviour is often a movement deficit.","Guard the child's dignity above the furniture.","Act early — the window narrows, it does not slam shut.","Do your part; the result is Allah's."],"nuggets":[{"q":"Playing is a real need of our children… As parents, if we recognize something is a need of our child, then we'll make it happen. But we deal with needs differently than we do if a child's being spoiled and demanding.","ts":60,"note":"The reclassification that the whole lecture rests on."},{"q":"This need for playing active physical games, unfortunately, is one of the most neglected parts of Islamic tarbiyah.","ts":123,"note":""},{"q":"If I believe that that's all the kid needs — to be entertained and kept busy — you know what the normal easy way out is? TV, phone, screen. Entertained, kept busy. Alhamdulillah.","ts":677,"note":"The sharpest diagnostic sentence in the lecture. The screen is not competing with play as play; it is competing with play as containment."},{"q":"Unmotivated parents — not only will they not create the games or the grounds for their children to play the active games, they'll stop them when they want to play.","ts":1226,"note":"The line to reread. Omission quietly becomes suppression."}],"practices":["Thirty hard minutes, every day, for Eliyya. Running, climbing, chasing, carrying, jumping. Not \"outside time\" — hard movement. This is the direct application of al-Kafi 6:47 h.3 ✅ (al-Majlisi muwaththaq, Behbudi sahih) and the one intervention with an actual intervention study behind it (Roslund 2020). [11:17]","Ask the movement question before the discipline question. When either child is difficult: how many minutes has this child moved hard today? Under thirty, treat the deficit first. [25:32] ⚠ My operationalisation of his point, but it follows directly.","Fifteen alert minutes, not sixty exhausted ones. [36:42] The measurable version of \"tarbiyah is the priority\" is whether it gets your good hours or your leftover ones.","Restore one piece of incidental movement. Park at the far end. Walk the errand. Send Abbas on foot with something for a neighbour. [22:29–24:30] It needs no scheduling and competes with nothing.","Keep the play promises. «وَإِذَا وَعَدْتُمُوهُمْ شَيْئاً فَفُوا لَهُمْ» — \"and when you promise them something, keep it\" (al-Kafi 6:49 ch. 35 h.3, majhul). ⭐ \"We'll play after Maghrib\" is a promise, and the narration's reason is devastating: \"for they know nothing except that it is you who provide for them.\""],"questions":{"parent":["Where in my own life have I substituted artificial satisfaction for the real thing — so that I no longer feel the pull toward my children? [31:36] Be specific: name the app, the show, the habit.","When my child is being difficult, what is my first hypothesis? Disobedience, tiredness, or unmet movement? [25:32]","In the last week, how many times did I stop physical play because it was inconvenient for me, and how many times did I start it? [20:26]"],"spouse":["Do we agree that physical play is a need? If one of us says \"need\" and the other says \"nice,\" we will undermine each other every day this month. [01:00]","Which of us is the sedentary parent, and which is the moving one — and whose lifestyle currently wins in this house? [24:30]","What are our actual screen numbers — hours per child per day, and bedtimes pushed late? Not our impressions; the numbers."],"family":["What is the best game we have ever played together as a family?","What game could we play in this house tonight that needs nothing we don't already own?","Abbas: what is a game you wish Baba would play with you but he never does?"]},"activities":{"abbas":["The Movement Log (real-life challenge + discussion)","Two Words: Kasal and Dajar (character-building)","The Bridge Captain (character-building + bonding)","The Family Game List (discussion + real-life challenge)","The Patch Story (story + discussion)"],"eliyya":["Thirty Minutes of Loud (play-based learning)","Dirt Day (play-based, and the one with a study behind it)","The Promise Kept (emotional development)","Baba Becomes a Child (parent-child bonding)","The Copy Game (Islamic manners + gross motor)","The Feelings Run (emotional development)"]},"corrections":[{"claim":"\"Beware of two traits\": no drive → won't see things through; laziness → won't observe others' rights","status":"⚠ MODERATELY VERIFIED — wrong Imam","note":"Wording and gloss are Imam al-Baqir's, Tuhaf al-'Uqul, short maxims no. 31; chainless, ungradeable. ⭐ His two consequence-clauses are exactly right and in the right order."},{"claim":"\"Let your son play for seven years\"","status":"✅ STRONGLY VERIFIED","note":"al-Kafi 6:47, bab ta'dib al-walad, h.3. al-Majlisi muwaththaq; Behbudi sahih. ⚠ h.3 is declarative, not imperative; the imperative version (h.1) is mursal. ⚠ Both outcome-bearing versions carry a failure branch he omits."},{"claim":"Child becomes halim after seven years if energy is released","status":"⚠ MODERATELY VERIFIED","note":"al-Kafi 6:51, ch. 37 h.2 — Imam al-Kazim (a), not al-Sadiq, and not the 7-7-7 hadith. al-Majlisi: majhul. Operative word is 'aramah (boisterousness), not \"energy.\" ⚠ The circulating corollary \"worry about a quiet child\" is NOT in the Arabic."},{"claim":"Play is \"hardwired into their fitrah\"","status":"❌ NOT A NARRATION","note":"Fitrah narrations (al-Kafi 2:12–13, h.2 and h.3 sahih) gloss fitrah as al-tawhid. No text links play to fitrah. Rhetorical use of a technical term."},{"claim":"Muhammad & Murazim after Hajj; \"sitting with him would have been better than your prayer in the masjid\"","status":"❌ NOT LOCATED — do not attribute","note":"Absent from al-Kafi 3/3/6, 3/3/8 and 2/1/83. ✅ The names are real — Murazim b. Hakim al-Mada'ini ↔ \"from Madan\"; a Muhammad b. Hakim is listed alongside him — so it may be genuine and unreached. ⭐ Substitute: al-Kafi 2 ch. 83 h.6 (majhul)."},{"claim":"Allamah Tabataba'i offers the thawab of all of al-Mizan for one night nursing a sick mother","status":"❌ NOT LOCATED — do not attribute","note":"Floating anecdote, also told of Ayatollah Bahjat and others. No memoir or biography carries it. ⭐ Substitute: Bukhari 3004 / Muslim 2549, «فَفِيهِمَا فَجَاهِدْ» (sahih)."}],"counts":{"verses":3,"narrations":14,"audit":35}},{"n":10,"slug":"lecture-10-the-four-traits-of-good-play","title":"Playing With Your Child: The Four Traits of Good Play","video":"ToQp2yam6U8","minutes":45,"thesis":"In the first seven years the parent's strategy is to make the child feel intensely loved — and the single most powerful instrument for that is play. But not any play. Shaykh Usama's claim in Part 10 is that play carries a message whether or not the parent intends one, and that the message depends on how the parent plays: whether he is merely present, whether he is willing, whether he initiates, whether he can lower himself into the child's world, whether the game moves the body, and whether the child can play it without fear.","why":"Part 9 argued that children must move; Part 10 argues that the parent must move with them, and that the parent's willingness to look undignified in front of his own child is a spiritual matter, not a temperamental one. For a father of a 7-year-old and a 4-year-old, this is the most immediately actionable lecture in the series so far: everything in it can be done tonight, costs nothing, and require","topics":[{"t":"The strategy restated, and the five effects of a love-filled home","a":0,"b":182},{"t":"The eleven practices that convey love","a":182,"b":305},{"t":"The fourteen traits, and Trait 1: parental involvement and active participation","a":305,"b":368},{"t":"The gradient of parental involvement, in five case studies","a":368,"b":1100},{"t":"Trait 2: being a child with your child","a":1100,"b":1343},{"t":"Half-hearted play versus real play: Rafiq, and Ahmed and Mahnaz","a":1343,"b":1586},{"t":"The Prophetic example: children on the Prophet's mount","a":1586,"b":1706},{"t":"Trait 3: active games, and the sedentary misreading of childhood","a":1706,"b":1950},{"t":"The no-running case study: how a house rule ends in a video game","a":1950,"b":2193},{"t":"The 'arama narration, and \"false excitement\"","a":2193,"b":2318},{"t":"Trait 4: games free of fear and anxiety, and the flowerpot","a":2318,"b":2682}],"takeaways":["The question is not whether you love them. It is whether they can feel it.","Allah's mercy toward you is proportioned to the intensity of your love for your child.","Play carries a message whether or not you intend one — and the child receives it before he has words for it.","There is a five-rung ladder of involvement, and most of us are two rungs lower than we think.","\"Whoever has a child, let him become a child for him.\"","What stops a parent playing is usually pride, not schedule.","Influence goes to whoever the child experiences as delighted by him — and it is not allocated by title.","Some of what gets called ADHD is a child being the youngest in the class — and ADHD is also real.","Liveliness in a small child is a good sign — but the Imam recommended it, he did not order it, and he said nothing about the quiet child.","A game a child has to play in secret is not doing tarbiyah."],"principles":["Love is not the variable. Transmission is.","In years 0–7, play is the medium.","How you play is the message: furniture / extracted / willing / initiating / initiating together.","The obstacle is pride, not time.","A small child receives tone and pattern, not sentences — and single bad evenings recover.","Movement is a need. What you forbid, you owe.","A game played in fear does no tarbiyah.","Prohibition without substitution produces concealment, and concealment is a transferable skill.","Relocate and supply, do not forbid.","Influence goes to whoever the child experiences as delighted by him.","Say which register you are speaking in: Allah / the Imam / me."],"nuggets":[{"q":"We all feel intense love for our children. The trick is: does my child growing up in this house — do they feel intense love?","ts":0,"note":"The sentence the whole lecture hangs on. Love is not the variable; transmission is."},{"q":"Just because they don't have the words for it doesn't mean the child is not getting the message loud and clear.","ts":797,"note":"His strongest developmental claim, and the research is on his side. ⚠ Trim \"loud and clear\" to \"the tone, and the pattern over time.\""},{"q":"The way that I interact with my kid is: 'I don't have energy for you, I don't have time for you, I don't like you.' That message is coming through.","ts":735,"note":"The message you did not intend is still the message that arrived."},{"q":"Even better than being a willing participant is when the parent says: do you want to play a game? I'm coming to you to play a game.","ts":490,"note":"Rung four. The difference between available and wanted."}],"practices":["The first ninety seconds. When you come through the door, before the phone, before the mail, before asking what's for dinner: greet the children by name and touch them. ✅ This is the one part of the Prophetic narration that survives verification intact — a man returning from a journey, met by children who had learned to expect it, making room for two of them before he had even reached home (Sahih Muslim 2428a). And if you want a text specifically for the greeting: al-Khisal p. 271 h. 12, \"and greeting children, so that it may be a sunnah after me.\"","One initiated game per child, per day. Not \"I'm available.\" \"Do you want to play a game?\" [08:10–09:13]. Five minutes counts. The rung you are on matters more than the duration.","Acknowledge instantly, even when you cannot come. The Ibrahim move [13:17]: smile at the child and say \"I'll be with you in a minute\" — and then shorten the adult thing rather than lengthening the child's wait. ⭐ And keep the promise: \"if you promise them something, fulfil it, for they know none but you provides for them\" (al-Kafi 6:49–50 ch. 35 h. 3, majhul).","Kiss them. ✅ The encouragement is real (al-Kafi 6:49 ch. 35, whole chapter). ❌ Just do not attach a rank in Paradise to it — the narration says a good deed, and it is da'if.","Check your face before you speak. The flowerpot boy \"is reading his father's face\" [43:42] before anything else happens. Whatever else you fix, fix the face first."],"questions":{"parent":["On the five-rung ladder — furniture, extracted, willing, initiating, initiating-together — where was I this week with Abbas? With Eliyya? Are they the same rung, and if not, why not?","When was the last time one of my children saw me enjoying myself in a game rather than administering one? Could they tell the difference?","What do I actually do in the first ninety seconds after I come through the door — and what would my children say I do?"],"spouse":["When did the two of us last play a game with each other that our children could see? [16:20–18:20]","Do our children ever hear us disagree across them, the way the mother in [11:15] made sure her husband could hear?","Which of us is the one the children go to first for play, and is that a division we chose or one that happened?"],"family":["What is your favourite game to play with Baba? With Mama? (Ask, then actually play it.)","What game do you wish we played more?","When was the last time you saw Baba being silly? (Let them enjoy answering.)"]},"activities":{"abbas":["The Rung Ladder, drawn on paper (discussion prompt)","Three Registers (character-building, and the most valuable thing in this section)","Chase Nights (real-life challenge)","The Story of the Three on One Mount (a story, told correctly)","Be The Grown-Up For Ten Minutes (character-building, humility both ways)","The Repair Log (real-life challenge, for the anxious activity)"],"eliyya":["Follow The Leader, and she is the leader (play-based learning)","The Yes Corner (emotional development; the flowerpot lesson, made small)","Stampy Feet Hide-and-Seek (parent–child bonding)","Two Big People Playing (emotional development, and the highest-value ten minutes in this section)","Salaam To The Small People (Islamic manners)","The Minute Promise (emotional development; keeping your word)","The Clay And The Tray (play-based learning; the closing move of the lecture)"]},"corrections":[{"claim":"Five effects of a love-filled home [01:01]","status":"⚠ CONTEMPORARY SYSTEMATISATION","note":"No classical enumeration. He claims none — to his credit. Items 3 and 5 have partial developmental support, but not as an Islamic list"},{"claim":"Eleven practices conveying love [03:02]","status":"⚠ MIXED — 6 of 11 have textual support","note":"Presented as a uniform block; the members are not equally sourced"},{"claim":"Calling children by their favourite names [03:02]","status":"❌ NOT LOCATED","note":"Kunya practice is real; the maxim is not"},{"claim":"Kissing your child → a daraja, 500 years between [03:02]","status":"❌ MEANING ALTERED — repeat of a settled error","note":"al-Kafi 6:49 ch. 35 h. 1 gives a hasana; the \"500 years\" is spliced from an unrelated family; al-Majlisi da'if, Behbudi excluded"},{"claim":"Hugging a believer for Allah → forgiveness, applied to children [04:02]","status":"⚠ SOUND TEXT, EXTENDED APPLICATION","note":"al-Kafi 2, bab al-mu'anaqa ch. 79 h. 2, hasan muwaththaq; conditioned on two adult mu'minun"},{"claim":"Stroking children's heads [04:02]","status":"⚠ WEAK / ADJACENT SUPPORT ONLY","note":"Nearest is al-Bayhaqi, Dala'il 1/298 (Subayh b. 'Abdillah al-Farghani, \"not well known\"); the orphan's-head narrations are a different subject"}],"counts":{"verses":3,"narrations":12,"audit":33}},{"n":11,"slug":"lecture-11-miracle-conditions-and-real-play","title":"Two Conditions for a Miracle & Play That Is Chosen, Varied and Real","video":"gQ0DpD9WV5k","minutes":35,"thesis":"Two theses run in parallel, and the lecture's shape is the relation between them.","why":"","topics":[{"t":"Tarbiyah as a near-miracle, and the two conditions for seeing it","a":9,"b":378},{"t":"The pop quiz, and the recovery of the first principle","a":378,"b":560},{"t":"The trick question: authority in the house, and the wife who humiliates you","a":560,"b":744},{"t":"Proactive patience and its three signs","a":744,"b":807},{"t":"Characteristic 5: freedom of choice in play","a":807,"b":1173},{"t":"Characteristic 6: variety","a":1173,"b":1417},{"t":"Free children invent their own games; scolding drives play underground","a":1417,"b":1539},{"t":"Characteristic 7: real and natural","a":1539,"b":1846},{"t":"The creativity case study: Raheem, and the Legos given away","a":1846,"b":1967},{"t":"Characteristic 8 named in passing, characteristic 9 begun, and the cut","a":1967,"b":2105}],"takeaways":["A miracle has two conditions: conviction, and your own act.","Your children's obedience is not your KPI; your own consistency is.","When your spouse wrongs you in front of the children, defer the conversation; do not cancel it, and do not retaliate.","A game the parent chose is not play.","\"No\" without a substitute is heard as a ruling about the child.","Variety is a logistics problem, and screens beat you on logistics, not on fun.","Secret play is not play; it is play with anxiety mixed in.","Children prefer real things — and this is a replicated finding, not a homily.","Outdoors works, and it works quickly — but not for a day.","Children need both competitive and cooperative games, and most homes supply only one."],"principles":["Do your part; the outcome was never your assignment. Shake the trunk.","If you support Allah, He supports you — and the first support you receive is a steadier heart.","The warm home comes first. Everything else is built on it.","When wronged in front of the children: defer, do not retaliate, do not drop it.","The child chooses the game. Dangerous and inappropriate are not choices.","Variety, or the game dies. Write the list.","Real over pretend. Outdoors over indoors. Open-ended over finished.","Say no in three parts: stop — one sentence — the same play made safe.","What you punish, you push underground.","Cooperate on good; race toward forgiveness. Both, deliberately, every week."],"nuggets":[{"q":"We are trying to raise our children to become soldiers of the Imam, and we're raising these children in the belly of the beast — where everything is pulling away from Allah and His Messenger.","ts":134,"note":""},{"q":"In order to experience our miracles, it's not just magical thinking… Rather, like the great prophets, we also have to do the part that's on our side. So if we are Musa, we have to throw the staff. If we are 'Isa… we have to take that clay, make that bird. Like Sayyida Maryam, we have to shake the tree.","ts":378,"note":"— The lecture's best passage, and the one worth memorising. ⚠ Attribute the Maryam lesson to Makarim Shirazi, not al-Mizan."},{"q":"Even if my spouse is not doing the right things, there's a higher principle — the principle of tranquility… It doesn't mean we never are going to talk about it, we sweep it under the rug. Rather, we're going to do proactive patience.","ts":744,"note":"— Deferred, not cancelled. The second half is what makes the first half honest."},{"q":"Proactive patience means I'm just waiting for the right time to speak.","ts":744,"note":""}],"practices":["The three-option offer. Whenever play is on the table and you are tempted to assign it, offer three and let the child pick. Not \"shall we play?\" (which invites a negotiation) and not \"let's draw\" (which is an assignment). \"We have twenty minutes. Blocks, wrestling, or the story game?\" [13:27]","The substitution rule, said out loud. Every \"no\" this week gets three parts: stop the thing — one sentence of why — a substitute that preserves the same play. Plastic jar for glass jar. Cushion-wrestling for jumping off the arm of the sofa. Sidewalk chalk for pen on the wall. [25:39]","Twenty minutes outdoors, every day, no exceptions for weather. Treat it as a dose. Faber Taylor & Kuo (2009) measured a concentration benefit from a twenty-minute park walk; ⚠ expect it to fade, which is an argument for daily, not for long. If there is genuinely no time, the nushra narration's item is looking at greenery — a walk to the end of the road and back, looking at trees, is a real instance of a religiously commended practice.","One real implement per day. A real spoon, real dough, a real screwdriver with you holding the other end, real coins in a real shop. Taggart, Heise & Lillard (2018) is the warrant, and this costs nothing. [26:40]","Notice one moment of secret play — and welcome it. Not as a technique but as a check on yourself: if you find a child enjoying something harmless out of your sight, the correct response is pleasure, not investigation. [24:39]"],"questions":{"parent":["In the last week, how many of the games my children played did they choose? Count honestly. What proportion is that?","When I say no to a game, do I give a reason and a substitute — or just the no?","What is the game I always suggest because it costs me least? (Everyone has one. Fatima's was twenty questions.)"],"spouse":["Which of us is the \"no\" in this house, and is that division deliberate or accidental?","Have we ever overturned each other in front of the children? What did the child's face do?","What are the three household rules about play that we have never actually agreed out loud — we just each assume the other holds them?"],"family":["What is the best game we have ever played together as a family?","If we could invent a brand-new game this weekend, what would be in it?","What is a game you love that we haven't played in a long time?"]},"activities":{"abbas":["The Game List — he writes it, not you","Discussion prompt — \"cooperating on what?\"","The story — Maryam and the palm trunk","Character-building exercise — the Deferred Grievance","Real-life challenge — the Real Thing project"],"eliyya":["Play-based learning — the Real Kitchen Drawer","Emotional development — the Plastic Jar Drill","Islamic manners — the Greeting Game","Parent–child bonding — Twenty Minutes of Mud","Emotional development — Naming the Feeling in the Story","Cooperative play — Beat the Timer, Together"]},"corrections":[{"claim":"\"Allah defends the believers\" [05:17]","status":"✅ Strongly verified — Q 22:38","note":"Paraphrase accurate. ⚠ al-Mizan: «فهو إنما يدافع عن دينه الذي عند المؤمنين» — the object is the religion in the community, not individual outcomes"},{"claim":"The competition verse (recording cuts) [34:48]","status":"✅ Resolved — Q 57:21","note":"Named at the opening of Part 12. Not 2:148 or 5:48. ⚠ al-Mizan on 57:21 was not retrieved"},{"claim":"Maryam shaking the palm → \"do your part\" [06:18]","status":"⚠ Lesson ABSENT from al-Mizan AND Majma' al-Bayan","note":"Sourceable to Makarim Shirazi, Tafsir-e Nemuneh (English An Enlightening Commentary vol. 9). Never attribute it to al-Mizan"},{"claim":"Nushra — \"all of these are outdoor things\" [27:41]","status":"⚠ Moderately verified — al-Khisal → Bihar 66:291; no grading","note":"Item 3 is immersion, not swimming; item 2 is riding generally; the ten items are not all outdoor"},{"claim":"\"Dirt is the springtime of children\" [28:43]","status":"❌ No Shia source; Sunni only (al-Tabarani 6/140 no. 5775), discussed under suspicion of fabrication","note":"The Prophet-and-companion narrative frame is not in the text either. Do not repeat as a hadith"},{"claim":"Swimming and archery [28:43]","status":"⚠ Moderately verified — al-Kafi 6:47 h.4; marfu'/da'if (al-Majlisi), excluded by Behbudi","note":"\"And play\" is an addition; \"and horse-riding\" is not in the Shia text"}],"counts":{"verses":7,"narrations":9,"audit":31}},{"n":12,"slug":"lecture-12-cooperative-play-and-the-watching-parent","title":"Cooperative Play, Games That Bear Fruit, and the Watching Parent","video":"NmjdceUPshY","minutes":46,"thesis":"A child's play is not a holding pattern until real life starts. It is the apparatus by which a child acquires four capacities that cannot be installed later by instruction: the ability to cooperate, the ability to see that his own effort changes the world, the ability to be watched and to perform well under a loving eye, and the ability to handle imperfect people in imperfect situations. Shaykh Usama's argument across these forty-six minutes is that each of these is built by a specific kind of game, and that a childhood spent on the wrong kinds of game — chiefly the solitary, resultless, screen-mediated kind — produces an adult who is missing the corresponding capacity and cannot easily be given it.","why":"Part 12 is the most usable lecture of the series so far. Almost every item converts directly into something a parent can do this week with a seven-year-old and a four-year-old, and the case studies are unusually concrete. It is also, on the evidence, one of his better-sourced sessions: the samit narration is hasan by al-Majlisi and sahih by Behbudi; the Mina story is attested twice inside the Four","topics":[{"t":"Two hardwired drives: to compete and to cooperate","a":0,"b":185},{"t":"\"Learning to be a good soldier\": the silent Imam","a":123,"b":185},{"t":"Case study: the cousins at the grandfather's house","a":185,"b":487},{"t":"The one-man game, the independent child, and the little dictator","a":487,"b":669},{"t":"Games that bear fruit: the child's footprint on the universe","a":669,"b":973},{"t":"The video-game excursus","a":973,"b":1402},{"t":"Case study: the wise mother","a":1402,"b":1644},{"t":"Point 11: the watching parent","a":1644,"b":1889},{"t":"Point 12: indoor and outdoor balance, and graduated exposure","a":1889,"b":2132},{"t":"Case study: the child brings home a bad word","a":2132,"b":2317},{"t":"Supervise without hovering","a":2317,"b":2378},{"t":"The moral compass, the parental contract, and Shahid Mohammad Memarian","a":2378,"b":2744}],"takeaways":["A child needs three kinds of game: solitary, competitive, and cooperative — and only one of them arranges itself.","Not-leading is not a defect.","Play should leave something behind that the child can point at.","Watching your child play is not optional, and it is the cheapest thing on the list.","When a child carries his game to your feet, he is making a bid.","Small fights between children are healthy, and the exception is bullying.","Total protection is a strategy with a catastrophic, late failure mode.","Haggle hard — and then be generous.","Bite your lip.","Do not revise the standard to fit your failure."],"principles":["Nahj al-Balagha, Letter 47 — taqwa, ordering your affair, and setting right what is between you. Three items. Do not drop the third.","Nahj al-Balagha, Hikmah 449 — «من كرمت عليه نفسه هانت عليه شهوته» — whoever holds his own soul in honour finds his appetites contemptible.","The wrestling match — al-Fusul al-Muhimma 2:757, from Imam al-Sadiq (a). ⚠ Her objection: \"al-Husayn is younger and weaker of frame.\" His answer: \"I say 'Go on, Hasan' and Jibra'il says 'Go on, Husayn.'\""],"nuggets":[{"q":"We as human beings have been hardwired so that we both need to compete. We also need to cooperate.","ts":61,"note":"The thesis of the first ten minutes. ⚠ The verses he cites command both; they do not describe the appetite."},{"q":"No, you can't have two imams at the same time — except if you have a silent imam.","ts":185,"note":"✅ al-Kafi 1, Kitab al-Hujja, ch. 5, h. 1 — hasan / sahih. The best-graded citation in the series. ⚠ Al-Majlisi supplies the al-Hasan/al-Husayn identification; the hadith names nobody."},{"q":"When are we going to learn — or our children to learn — how to even be a good soldier?","ts":185,"note":"⚠ His image, not the hadith's claim. But the safe half is worth carrying: not-leading is not a defect."},{"q":"Before we decide what game we're going to play, let's pick a leader.","ts":306,"note":"The children in his case study get the sequence right: consult, then appoint, then act."}],"practices":["Look up when the game arrives at your feet. [29:27] Zayn on the phone and Marwa in her headphones are the two named failures, and they are the two most common evening postures in a modern house. When a child relocates his play into your room, that is a bid. Answer it inside ten seconds, even if only with \"show me.\"","Watch, and be seen watching. [27:24] Five minutes of visible attention to whatever they are doing. Not participation — attention. This is the specific practice he offers to parents who cannot give much time.","Cheer, coach lightly, and report. [28:25] Three moves: \"masha'Allah\"; one concrete suggestion, offered not imposed; and then tell someone else about it in the child's hearing. The third is the one adults forget and children remember.","Bite your lip once a day. [36:34] Whenever a child reports something shocking, the first two seconds decide whether they report the next thing. Name the act, not the child; protect the third party's dignity; take the adult's share yourself.","Do not sin in front of them, and if you fall short, say so — without revising the standard. [39:38] \"What's right is right. What's wrong is wrong. It doesn't matter what I'm doing.\""],"questions":{"parent":["Of the three kinds of game — solitary, competitive, cooperative — which did my children have this week, and how many times? Count, do not estimate. Which one did I have to arrange, and did I arrange it?","When did I last watch one of my children play, to the end, without a phone in my hand? What did I see that I had not noticed before?","What happened the last time one of my children reported something shocking to me? Did my reaction make the next report more likely or less?"],"spouse":["What is our parental contract? [39:38] Write down three things neither of us will do in front of the children — and one thing we will always do.","When one of us falls short of it, what is the agreed repair? Who says what, in front of whom?","Which of us is the natural hoverer and which the natural stepper-back? Neither is right on its own. How do we cover for each other?"],"family":["What is the best game we have ever played all together? What made it good?","Can you think of a game where you had to work with somebody else or it would not work at all? How did you decide who did what?","Who picks the leader when you play with cousins or friends? How do you pick? Is that a good way?"]},"activities":{"abbas":["The Mud House (cooperative play / real-life challenge)","The Mint for the Lemonade (character-building / patience)","The Fair Match (discussion + story)","Both Halves (discussion, five minutes, repeatable)","The Errand (graduated exposure)","The Bad Word Rehearsal (character-building, done in advance)"],"eliyya":["The Poster Board (play-based learning)","Under the Sheet (parent–child bonding)","One Job in the Big Job (cooperation, at four)","Growing Something Fast (play-based, patience at four-year-old scale)","I See You (emotional development)","The Careful Hands (Islamic manners)","Outside, Loud, Dirty (play-based, and non-negotiable)"]},"corrections":[{"claim":"…therefore competition is \"hardwired into the fitrah\"","status":"⚠ Homiletic extension","note":"The verse commands a race; it does not describe an appetite. And the fitrah narrations gloss fitrah as al-tawhid"},{"claim":"Q 5:2 — cooperate in righteousness","status":"✅ Verified, honestly labelled as partial","note":"⚠ The omitted half — do not cooperate in sin and aggression — is the operative limit, and the preceding clause restrains vengeance. Also: the verse commands cooperation, it does not describe a need"},{"claim":"Q 30:41 — corruption from human hands","status":"✅ Verified","note":"al-Mizan affirms «بين أعمال الناس والحوادث الكونية رابطة» and takes barr/bahr literally. ⚠ Note ba'da — only part of the consequence"},{"claim":"Q 7:96 — blessings on the towns","status":"✅ Verified","note":"⚠ Addressed to communities (ahl al-qura), and counterfactual about towns that were destroyed. The individualising move is homiletic"},{"claim":"Q 35:14 — none informs like the All-Aware","status":"⚠ Verified text, decontextualised use","note":"The khabir is God; the subject is the futility of shirk; the address is to the Prophet (s). Not a maxim about human expertise"},{"claim":"…therefore \"followership is a virtue / be a good soldier\"","status":"❌ Not supported","note":"al-Majlisi's samit is silent about da'wah, self-identification and claiming the imamate — a doctrine of manifest authority, not of teamwork"}],"counts":{"verses":5,"narrations":7,"audit":34}},{"n":13,"slug":"lecture-13-trial-error-defeat-and-video-games","title":"Trial, Error, Defeat, and the War on Video Games","video":"P01SNTy5aik","minutes":38,"thesis":"This lecture finishes the \"fourteen traits of good play\" that has run since Part 9, and then pivots the whole series into its hardest confrontation. The finishing move is two more traits: some of your child's games must build an experience base through trial and error, and some must be competitive, so the child tastes both winning and losing while the stakes are still a plastic ball on a living-room floor [01:02–12:11]. The confrontation is video games, which he does not treat as one more screen problem but as the single threat capable of undoing everything the previous twelve lectures built:","why":"Movement 3 contains this series' sharpest single insight and its worst sourcing. The insight is the Imam Ali / Ibn Muljam test [23:20]: a child trained for hundreds of hours in a world where killing is the scoring mechanism will hear that Imam Ali (a) woke his own assassin for fajr and will not be able to parse it as virtue. That is not a psychometric claim about game violence, which is contested;","topics":[{"t":"Recap, and the rule that keeps the framework honest","a":2,"b":62},{"t":"Trait thirteen: games that build an experience base","a":62,"b":126},{"t":"Two case studies in over-coaching","a":126,"b":371},{"t":"Trait fourteen: competitive games, and the necessity of losing","a":371,"b":611},{"t":"Case study: hand tennis, two mothers, one four-year-old defeat","a":611,"b":731},{"t":"Why the gaming battle is different, and why it is now","a":731,"b":913},{"t":"Danger 1: addiction, tolerance, and artificially altered taste","a":913,"b":1156},{"t":"Danger 2: role-model substitution, and getting there first","a":1156,"b":1461},{"t":"Danger 3: the destruction of the work ethic","a":1461,"b":1642},{"t":"Danger 4: the imagination usurping the intellect","a":1642,"b":1763},{"t":"Danger 5: the loss of the physical outlet","a":1886,"b":2069},{"t":"Danger 6: academic failure, depression, and social atrophy","a":2069,"b":2249}],"takeaways":["Just enough help to get past the crisis point — not one hint more.","There are two failure modes, and correcting one can produce the other.","A child must lose while losing is cheap.","Comfort the child — but do not change the game.","","Love of a person carries what argument cannot.","","❌ Three things in this lecture must not be repeated as narrated.","❌ The addiction number is wrong by an order of magnitude — and the real argument is better.",""],"principles":["Judge the week's play, not the individual toy.","The challenge is the enjoyment — remove it and the motive goes with it.","Just enough help to pass the crisis point; not one hint more.","Comfort the child; do not change the game.","Attention on the method, not the outcome: \"what was he doing that you weren't?\"","Competition is the alternative to enmity, not its cause.","Get to the child before something else does.","Say what the day's work cost.","When the park stops working, something has moved.","Later is harder, not too late."],"nuggets":[{"q":"Just enough help to make the child pass the crisis period — but allow the child to think, understand, self-correct, figure it out.","ts":371,"note":"The single most usable sentence in the lecture, and the whole of Topic 3.3 in one line."},{"q":"Part of the enjoyment was the challenge.","ts":249,"note":"Why the over-helping mother destroys the activity and not merely the learning."},{"q":"You're doing it wrong, dear. She's helping. Quote unquote. She's helping.","ts":249,"note":"He hears himself say it, and repeats it so the room hears it too."},{"q":"'I lost.' Not that I lost the game. I lost.","ts":551,"note":"The distinction the whole competitive-play argument exists to prevent."}],"practices":["The five-second rule before you help. When Abbas or Eliyya is stuck at something, count to five before you speak. Most parental interventions happen inside three seconds, and most of them are unnecessary. [06:11]","Climb the ladder from the top. Silent presence → contentless encouragement (\"keep going\") → a hint that locates (\"look at the last two pieces\") → leave the room → direct help. Never start below the rung the situation requires. [05:11–06:11]","One Ahlul Bayt story, told as a story. Not a lesson with a moral bolted on. Three or four nights a week, at bedtime, with no follow-up quiz. This is badiru awladakum in its operational form — occupying the ground before anything else does. [20:16]","Say what the day cost. One sentence at dinner about the work: \"That was a hard day. I did it for you. Allah counts it.\" This is what replaces the forged Tabuk story — the lesson delivered by a father who is actually in the room. [24:21–26:22]","Notice one boisterous thing and let it happen. 'Aramat al-sabiyy is mustahabb (al-Kafi 6:51, majhul). Once a day, do not stop the noise. [31:26]"],"questions":{"parent":["When my child struggles, what am I actually afraid of — that they will fail, or that I will have to watch them be uncomfortable?","Which of the five rungs of the help-ladder do I habitually start on? Be honest about the last three times.","When did I last let one of my children lose at something, all the way through, without softening it?"],"spouse":["Are we the same parent on screen time, or is one of us the wall and one of us the door?","What did we allow this week that we had agreed we would not? What made it easy to allow?","Which of us over-helps and which of us under-helps? What does that do to each child?"],"family":["What is something you tried this week that did not work the first time? What happened next?","Who in this family is the best at losing? What do they do?","Tell me about a time you were beaten by a friend. Are you still friends?"]},"activities":{"abbas":["The Lifeline Jar — teaching him to want less help","Best-of-Five — losing on purpose, with a handshake","The Slow Build — four days of effort for one result","Character study: the night of 19 Ramadan","The Real-World Challenge — one thing that only works if you do the boring part"],"eliyya":["The Tower That Falls — play-based trial and error","Rolling Race — winning, losing, and the handshake","Big Muscles Before Screens — the discharge habit","\"If He Cannot See Me, I Can See Him\" — a story about a woman with an inner life","Emotional Weather — naming the feeling that follows a loss","Ten Minutes on the Floor — parent-child bonding, unstructured"]},"corrections":[{"claim":"Prophet (s) kisses the calloused hand after Tabuk; \"a hand the Fire will not touch\"; the man is Sa'd the Ansari [25:22]","status":"❌ FABRICATED","note":"Ibn al-Jawzi: mawdu'. al-Dhahabi: kadhib. No Imami source at all. Sa'd b. Mu'adh died 5 AH; Tabuk was 9 AH — the exact chronological impossibility the critics rejected it for. Ibn al-Athir invented a second \"Sa'd al-Ansari\" to save it"},{"claim":"\"Whoever works increases in strength\" — Imam Ali [25:22]","status":"❌ NOT LOCATED","note":"Not in Nahj; no dorar match on the reconstructions. Unsourced aphorism"},{"claim":"One who toils for his dependants is like a mujahid [26:22]","status":"⚠ MODERATELY VERIFIED","note":"al-Kafi vol. 5, Kitab al-Ma'isha, bab man kadda 'ala 'iyalih (5:88). No Sunni chain in this wording; the Sunni analogue (Bukhari 5353) is about widows and the poor. Grading unretrieved. This is the text he needed"},{"claim":"\"The intellect is the imam of the body, the imagination one of its soldiers\" [28:23]","status":"❌ NOT A HADITH","note":"Junud al-'Aql wa'l-Jahl (al-Kafi 1:21-23; al-Khisal 2:589) lists 75 moral qualities — no khayal, no wahm, no faculty of any kind. \"Heart as king with soldiers\" is a weak Sunni report (al-Albani: da'if) about the limbs. The idea is Ibn Sina → al-Ghazali → Mulla Sadra → Imam Khomeini's Sharh Junud al-'Aql — philosophy, not narration"},{"claim":"\"It is easier to move mountains than a heart once a belief is established\" [21:18]","status":"❌ NOT LOCATED","note":"Nothing in the Arabic corpora. Substitute: Nahj al-Balagha Letter 31, «فَبَادَرْتُكَ بِالْأَدَبِ قَبْلَ أَنْ يَقْسُوَ قَلْبُكَ»"},{"claim":"\"Sweet taste of victory erases the bitterness of patience\" [07:11]","status":"⚠ NEEDS FURTHER VERIFICATION","note":"«حَلَاوَةُ الظَّفَرِ تَمْحُو مَرَارَةَ الصَّبْرِ» — chainless Ghurar / 'Uyun corpus, entry unpinned. Not in Nahj. Not \"a hadith\""}],"counts":{"verses":5,"narrations":11,"audit":30}},{"n":14,"slug":"lecture-14-karamah-and-the-second-seven-years","title":"Karamah First: The Strategic Goals of the Second Seven Years","video":"xKsu_1BbjOw","minutes":57,"thesis":"The second seven years are not a discipline programme. They are a dignity programme. Shaykh Usama opens the last movement of the series by arguing that from seven to fourteen the parent's job is to install in the child a settled, God-anchored sense of his own worth — karamah — and then to let obedience, restraint, truthfulness and clean speech emerge from it, rather than being drilled onto it from outside. He names the method in the language of engineering:","why":"","topics":[{"t":"The goal stated: karamah is the child's right, not the parent's favour","a":167,"b":287},{"t":"Three verses that establish worth as given","a":287,"b":470},{"t":"The ladder, and the gold bar in the backpack","a":470,"b":717},{"t":"Reverse-engineering karamah","a":717,"b":958},{"t":"Mechanism one: the inner admonisher","a":958,"b":1199},{"t":"The doctor and the fever: compliance as a symptom","a":1199,"b":1380},{"t":"Mechanism two: the moral compass","a":1380,"b":1683},{"t":"Effect one: sin becomes disgusting, not merely forbidden","a":1683,"b":1986},{"t":"Effect two: the dunya becomes light in his eyes","a":1986,"b":2352},{"t":"How to talk to a seven-year-old about the dunya","a":2352,"b":2598},{"t":"Effect three: the child grows up truthful","a":2598,"b":2966},{"t":"Effect four: the child does not use foul language","a":2966,"b":3210},{"t":"The closing case study: Ahmed, fourteen, and the mother who never lifted her foot","a":3210,"b":3398}],"takeaways":["Dignity comes before restraint, not after it.","Honouring your child is his right, not your favour.","Human worth is given, and then it is earned — and these are two different things.","The gold bar in the backpack.","Fix the vertical relationship and the inner voice appears — quote the whole hadith.","Over-correction is a documented failure mode, not a matter of taste.","Compliance is a symptom to be diagnosed, not a result to be banked.","Most parent–child conflict is a weighting dispute, not a rule dispute.","Punished children lie more — and lying is also normal.","Describe the deed; do not label the person."],"principles":["Dignity before restraint — not the reverse.","Honour is his right, not your favour.","Worth is given (17:70) and earned (49:13). Teach both; never trade in comparison.","Fix the vertical relationship; the inner voice follows.","Compliance is a symptom. Ask what is powering it.","Check the weighting before enforcing the rule.","Shame manufactures the behaviour it punishes.","Describe the deed; do not name the person.","The dunya lesson is watched, not taught.","Keep the rules. Drop the hovering. Build an exit."],"nuggets":[{"q":"In order for the person to be careful, they need to know they're special. Then automatically, the taqwa will happen.","ts":null,"note":""},{"q":"The whole family, the future of the family is riding on you with your mission. It's a big ask, son, but you're up to it. I need you.\" … \"But let's say there was a kid who has no idea what's in the backpack — hand-me-down clothes, used sneakers. You see the kid take the same backpack: 'Sweet.' Throwing it at trees, trying to knock down fruit. Who cares what happens to the backpack?","ts":null,"note":""},{"q":"«مَنْ كَرُمَتْ عَلَيْهِ نَفْسُهُ هَانَتْ عَلَيْهِ شَهْوَتُهُ»","ts":null,"note":"\"His desires become insignificant to the person who has realised the value that they have with Allah.\" (his rendering, and it is accurate)"},{"q":"That external guide isn't always with us. But the inner voice — if it's powerful, it's with us, and Allah's with us.","ts":null,"note":""}],"practices":["Say the given thing out loud, once a day, in ordinary language. Not praise — disclosure. \"Allah honoured you before you ever did anything for Him.\" This is 17:70, and al-Mizan's takrim is exactly why it is not flattery: you are reporting a fact, not awarding a grade. Thirty seconds, at bedtime or in the car.","Run the weighting check before the enforcement. When Abbas has done something you consider serious, ask first: how bad do you think that was — a little bad, quite bad, very bad? Then compare. If the numbers differ, the argument you are about to have is not about the rule. [23:00–24:01]","One dignity-preserving correction. Every day there is at least one moment where the fast reaction is the labelling one. Replace the label with the description: not \"you're being lazy\" but \"the shoes are still in the hall.\" This is Khutba 206's substitution clause, and it is the single most transferable technique in the lecture. [50:28]","Do not correct in front of an audience. Siblings count as an audience. Guests count double. Mahanah is public by nature; that is what makes it mahanah.","Notice one thing he does that nobody asked him to do, and name it back to him. You are looking for evidence that the inner admonisher is switching on, and children repeat what gets noticed."],"questions":{"parent":["When was the last time I said something to Abbas that made him feel small — and would I recognise it if he could not tell me?","What is my honest answer to the shaykh's question to the mother at [54:31]: how long am I planning to do this kind of controlling tarbiyah?","Do my children behave well because they think they are valuable, or because they think I am watching? How would I even find out?"],"spouse":["Which of us is the enforcer and which is the softener — and is that division serving the children or just relieving us?","Are our two moral compasses calibrated the same? Name one act where we would score it differently, and settle it privately before the children hit it.","Do we ever discipline in front of the other children? What would it cost us to stop entirely?"],"family":["What does it mean to say Allah has made every human being karim — and can you be karim if nobody sees you doing anything good?","Which is worse: a big sin that nobody notices, or a small sin in front of everyone? (Then: \"O Abu Dharr, do not look at how small the sin is — look at whom you disobeyed.\")","If someone insults you, why is answering back beneath you? What would Imam 'Ali (a) have told his soldiers to say instead?"]},"activities":{"abbas":["The Backpack (discussion prompt + real-life challenge)","The Two Kinds of Honour (discussion prompt)","Beneath Me (character-building exercise)","The Wooden Spoon (story + discussion)","Say the Deed, Not the Name (real-life challenge, whole family)","The Turning Days (discussion + a real-life anchor)","One Thing Nobody Will Know (character-building)"],"eliyya":["The Precious Thing (play-based learning)","The Sorry Rules (emotional development + Islamic manners)","Kareem and Not-Kareem (Islamic manners, play-based)","Two Voices (emotional development)","Salaam to the Smallest (Islamic manners + bonding)","The Whole-Family Sit (parent-child bonding)"]},"corrections":[{"claim":"Q 49:13 — inna akramakum 'inda'llahi atqakum","status":"✅ Verse correct","note":"Used for acquired honour. ⚠ 49:13 makes karamah the result of taqwa; his thesis runs the other way. Both are true — they are karamah iktisabi and takwini. He should name the distinction"},{"claim":"Q 91:7–8 — fa-alhamaha fujuraha wa taqwaha","status":"✅ Strongly verified","note":"Correctly recited and correctly glossed. ⚠ The next verse — qad aflaha man zakkaha — is the operative half and he omits it"},{"claim":"Q 4:19 — \"Allah put much good in it\"","status":"✅ Reference right / ⚠ decontextualised","note":"khayran kathiran is 4:19, so his citation was correct. But 4:19's subject is marital ethics; 2:216 is the better general proof-text. Second lecture running with this swap"},{"claim":"«أكرموا أولادكم وأحسنوا آدابهم يغفر لكم»","status":"⚠ Chainless (Imami) / da'if (Sunni)","note":"Makarim 1:254; Wasa'il 21:476 h.27611; Ibn Majah 3671. ✅ He keeps yughfar lakum, which speakers usually drop"},{"claim":"«المؤمن يحتاج إلى توفيق من الله وواعظ من نفسه وقبول ممن ينصحه»","status":"⚠ Chainless","note":"Tuhaf al-'Uqul p. 457. Attribution correct; the third limb — accepting counsel — is the one he passes over"},{"claim":"«الكرم تنزّه عن المعاصي»","status":"⚠ Chainless, entry unpinned","note":"Ghurar al-Hikam. ⚠ ASR renders tanazzuh as \"tanazzul\" — the opposite word"}],"counts":{"verses":9,"narrations":19,"audit":43}},{"n":15,"slug":"lecture-15-the-six-fruits-of-karamah","title":"The Six Fruits of Karamah: Trust, the Gaze, Modesty, Akhlaq and Pardon","video":"ud4l_1INEvA","minutes":59,"thesis":"Everything a parent of a seven-to-fourteen-year-old spends their energy enforcing — honesty, keeping a promise, clean speech, control of the eyes, modesty, decent temper, letting go of a grudge — is downstream of one upstream cause. Shaykh Usama calls that cause karamah: the child's settled, felt knowledge of how valuable he is to Allah. Install that, and the behaviours follow without enforcement. Fail to install it, and you will spend the second seven years enforcing behaviours one at a time, forever, and losing.","why":"","topics":[{"t":"The recap: dignity as the master key","a":31,"b":397},{"t":"Foul speech, and what actually makes a school Islamic","a":397,"b":518},{"t":"Goal One: the child who honours a trust","a":518,"b":887},{"t":"Goal Two: the gaze, and the child your words can no longer reach","a":1249,"b":1434},{"t":"The spine: three signs of karam, and the failure of parental controls","a":1434,"b":1617},{"t":"Goal Four: 'iffah and ghayrah","a":1617,"b":1919},{"t":"The two mindsets, side by side","a":1919,"b":2102},{"t":"Shahid 'Abd al-Husayn Borunsi and the villa","a":2102,"b":2285},{"t":"Goal Five: real akhlaq versus performed akhlaq","a":2285,"b":2525},{"t":"The near-death account of Behrouz Azimi","a":2525,"b":2705},{"t":"Shahid Mahmoud Kaveh and the Basiji's photograph","a":2826,"b":2946},{"t":"Goal Six: the child who does not carry a grudge","a":2946,"b":3128},{"t":"Hastening to pardon, and the closing litmus test","a":3371,"b":3494}],"takeaways":["Dignity is upstream; behaviour is downstream.","Your window is temporary, and you know it.","Betrayal has three forms, and children only recognise one.","The quality of a child's promise is the diagnostic, not the offence.","Three signs of karam, and all three are self-restraint.","Sin degrades your leverage, not just the child's record.","Parental controls buy far less than you think — and conversation buys far more.","Real akhlaq is what happens at home when nothing is at stake.","Repeating the command is fuel, not pressure.","Four questions diagnose a household faster than any behaviour chart."],"principles":["Dignity is upstream; behaviour is downstream.","The window is temporary; build what survives your absence.","All three signs of karam are restraint under pressure.","Trust has three forms; teach all three.","Sin degrades receptivity — including yours.","Filters buy little; conversation buys most.","Real character is what happens at home.","Repetition is fuel in a coercive cycle.","The noble move first, not fastest.","Say what your sources are."],"nuggets":[{"q":"How long are we going to be able to be next to our children? … Are we going to hover over them? Right now we have this window where we're trying to install karamah, but we know that this is a temporary window.","ts":1434,"note":""},{"q":"A person who has karamah won't try to save themselves by lying to get out of it. They'll take it on the chin and they will own up to their mistakes.","ts":640,"note":""},{"q":"«ثَلَاثَةٌ تَدُلُّ عَلَى كَرَمِ الْمَرْءِ: حُسْنُ الْخُلُقِ، وَكَظْمُ الْغَيْظِ، وَغَضُّ الطَّرْفِ»","ts":1434,"note":""},{"q":"An Islamic school is not a school where they serve halal pizza.\" [07:38] — \"The bare minimum is that public sin is not tolerated or institutionalised.","ts":458,"note":""}],"practices":["✅ Say one true thing to Abbas each day about who he is, not about what he did. The whole lecture turns on the child's felt worth [23:54]. \"That was clever\" is about output. \"You are somebody who tells the truth even when it costs you\" is about identity, and identity is what the karim consults under pressure.","✅ Run the home test on yourself, silently, once a day [40:05]. Was the version of me my family saw today the same version my community saw? No score, no journal entry — just the question. This is the only diagnostic in the lecture that requires nothing from the child.","⚠ Answer question three of the four every day: use the name he likes. It is the cheapest of the Shaykh's four diagnostics [55:11] and the one most easily lost in a rushed morning. ⚠ Note that \"call people by their favourite name\" is not a located hadith; do it because it is obviously right, not because a narration commands it.","✅ Correct in private, always [55:11]. If the correction cannot wait, take him out of the room first. The Imami warrant is Nahj al-Balagha Hikmah 222 on taghaful — overlooking what you know — plus the Prophet's (s) practice of addressing a fault without naming the person.","⚠ Guard your own eyes where he can see you doing it. The lecture argues that ma'siyah degrades receptivity [22:53]. Turn the phone face-down when he enters. Look away, visibly, when something on a screen turns. He is learning ghadd al-tarf as a movement, and movements are learned by copying."],"questions":{"parent":["When was the last time I asked Abbas for his opinion on something that affects him — and then did what he said? [55:11] If I cannot name an instance from this month, what does that tell me about how much standing he has here?","Do I correct my children in front of other people? How often, and in front of whom? [55:11]","What name do I use when I am irritated with each child, and is it the name they like? [55:11]"],"spouse":["Between us, who is the one the children take a problem to first? What does the other one need to change to become a second option?","Answer the Shaykh's four questions [54:10–56:11] about each child separately, then compare. Where the two of you disagree about how you speak to a child, the child is the tiebreaker.","Is there a grudge inside our marriage that the children can feel? What is it costing them?"],"family":["What is an amanah? Can everyone name one thing that was placed in their trust this week — an object, a secret, and an expectation nobody wrote down? [11:45]","Why is it worse to betray someone who trusted you than to steal from a stranger?","If somebody betrays you, are you allowed to betray them back? What does Q 5:8 say?"]},"activities":{"abbas":["The Three Boxes (discussion prompt)","The Aziz Story, stopped three times (story)","The Eyelid Drill (character-building exercise)","Repel It With Better (real-life challenge)","Who Moved First? (character-building, family-wide)","The Home Test, run on the family (discussion, use with care)"],"eliyya":["The Amanah Game (play-based learning)","Look Away, Look Back (play-based, emotional development)","\"Don't Put It In Our Hearts\" (Islamic manners, bonding)","The Sorry Race (emotional development)","Guest of Honour (parent–child bonding, Islamic manners)","Softly, With Your Own Name (Islamic manners, bonding)"]},"corrections":[{"claim":"Q 64:6, \"shall human beings guide us?\"","status":"✅ verse & reading VERIFIED · ❌ attribution NOT VERIFIED","note":"Content is al-Mizan + Majma' al-Bayan verbatim. No Khamenei tafsir reachable; 403-blocked archive, not a completed negative"},{"claim":"\"Not the regular garden-variety kuffar\"","status":"❌ NOT VERIFIED","note":"Same phrase the index already flags from Part 2 on Surat al-Nur 47–50"},{"claim":"N1 sunnat al-li'am qubh al-kalam","status":"⚠ Moderately verified","note":"Ghurar 5550–5551; chainless; the paired positive half dropped"},{"claim":"N2 la tatakallamu bi'l-fuhsh…","status":"❌ NOT LOCATED","note":"Substitute Nahj Khutbah 206 — «إني أكره لكم أن تكونوا سبّابين» — which he used correctly in Part 14"},{"claim":"⭐ N3 addi'l-amanata… wa la takhun man khanak","status":"⭐ ❌ NOT ESTABLISHED","note":"Ahmad: batil · Ibn al-Jawzi: all routes invalid · Abu Hatim: munkar · al-Shafi'i: laysa bi-thabit · Ibn Hazm: la yasihh · only al-Tirmidhi 1264 hasan gharib. Sunni; no Imami chain. Substitute Q 4:58 + Q 5:8"},{"claim":"N4 al-kadhib wa'l-khiyanah laysa min akhlaq al-kiram","status":"⚠ Moderately verified","note":"Chainless maxim; entry unpinned. His gloss is the best sentence in the section"}],"counts":{"verses":5,"narrations":22,"audit":43}},{"n":16,"slug":"lecture-16-mudara-service-and-muwasat","title":"Mudara, Service and Muwasat: Finishing the Karim at Fourteen","video":"kTGFDLPB6Vk","minutes":63,"thesis":"Karamah — a person's felt nobility before Allah — is not finished when a child stops lying and starts guarding his tongue. It is finished when he can absorb other people. The last three traits Shaykh Usama installs are all outward-facing: mudara (amicable, principled dealing with imperfect people), service to others, and muwasat (sharing your own wealth with a brother as an equal). A child who has the inward traits of Parts 14–15 and none of these three is, in the Shaykh's diagnosis, a child who can only function in a vacuum — and the world is not a vacuum.","why":"The series ends where it began: with the parent. Every trait in this lecture is one the child acquires by watching — the mother who forgives the slap, the father who does the errand without being asked twice, the household where a guest's need is a blessing and not an imposition. And it ends on the most demanding sentence in sixteen hours of material: if someone needs you, that need is one of Alla","topics":[{"t":"The dead, the barzakh, and legacy as a tarbiyah subject","a":36,"b":404},{"t":"Karamah as the master trait, and the ten-point recap","a":404,"b":708},{"t":"The litmus test, and the objection he honestly defers","a":708,"b":829},{"t":"Shahid Mohammad Boroujerdi: two stories","a":829,"b":1136},{"t":"Mudara: naming the trait, and four goals by fourteen","a":1136,"b":1318},{"t":"Four postures toward an imperfect world","a":1318,"b":1561},{"t":"The fourth posture, and the hadith that carries the lecture","a":1561,"b":1622},{"t":"Case study: Sara's first day of school","a":1622,"b":1925},{"t":"Mudara for the deen: the verse, and the two tiers","a":1925,"b":2108},{"t":"Imam al-Kazim (a) and the farmer outside Medina","a":2108,"b":2289},{"t":"Service to others","a":2289,"b":2410},{"t":"Imam al-Sajjad (a), the weeping, and the two loaves","a":2410,"b":2712},{"t":"Muwasat, and the three tests of Shi'ism","a":2712,"b":2897},{"t":"Shahida Tahereh Hashemi","a":2897,"b":3020},{"t":"Helping as a responsibility: two kinds of grown child","a":3020,"b":3262},{"t":"Shahid Mehdi Bakeri and the water jugs","a":3262,"b":3322},{"t":"Case study: Aasim and Najma","a":3322,"b":3504},{"t":"The karim and the la'im on debts of kindness","a":3504,"b":3687},{"t":"Joy through service, and the closing hadith","a":3687,"b":3748}],"takeaways":["Mudara is commanded in the same breath as the obligatory acts.","The child who cannot tolerate imperfect people has been handicapped, not indulged.","The litmus test of karamah is what you do when you are wronged — and it is Imam 'Ali's (a).","Mockery is part of the package, and a child should be told in advance.","Empathy precedes means. The Imam wept for a man he could not help.","Muwasat comes across, not down.","Shi'ism is defined by conduct, not by census.","The tell is what a parent feels when a child helps.","Imtinan — reminding people of your favours — nullifies them.","Other people's needs of you are a blessing that can be moved."],"principles":["A child who can only function in a vacuum has not been raised; he has been insulated.","Mudara stands beside the fara'id — it is a taklif, not a temperament.","Amicable, without abandoning a right. Teach both halves or you have trained a target.","Being mocked for visible practice is structural, not personal (36:30). Say so before it happens.","Service is watched, not taught. What is narrated aloud stops being service.","Muwasat goes across; sadaqa goes down. A child should know the difference by fourteen.","Prayer on time and money actually shared are the two tests that survive every recension.","Notice what you feel when a child helps you — glad or wary. That feeling is your report card.","\"After everything I've done for you\" converts the parent into the la'im of the pair.","A person's need of you is a ni'mah placed with you — and blessings are movable."],"nuggets":[{"q":"For us, it's a small thing to read du'a for them. But the hadith tell us that the mayyit, the person who has left this world, gets so excited, so happy when somebody asks for mercy for them — kama yafrahu al-hayyu bi'l-hadiyya. The same way a living person is happy if you were to come over and give a gift to somebody who wasn't expecting it.","ts":98,"note":"The fatiha as a gift arriving"},{"q":"If I'm just completely honest with you — when I personally hear these hadith, I know I have a lot of work to do. I look at this hadith… no, I have a lot of work to do. All of us have a lot of work to do.","ts":464,"note":"He puts himself in the dock first"},{"q":"We don't want our children raised in such a way that I can only thrive if I'm in a vacuum — if I'm in a world where everybody thinks like me and works like me and acts like me. No. I'm in a world which is imperfect, with different people, different cultures, different personalities.","ts":1197,"note":"The child who can only live in a vacuum"},{"q":"Swallowing anger does not mean we don't get angry. It means: once I'm angry, do the gloves come off — or am I still under the control of Allah?","ts":1257,"note":"What swallowing anger actually means"}],"practices":["Do one visible act of service in the house without being asked and without narrating it. [40:10] The children must see service happening; they must not hear you claim it. If you catch yourself about to say \"I did the bins again,\" stop.","Say the mudara hadith to yourself once when you are irritated by someone. «أَمَرَنِي رَبِّي بِمُدَارَاةِ النَّاسِ كَمَا أَمَرَنِي بِأَدَاءِ الفَرَائِضِ» — commanded, like the fara'id. ✅ al-Kafi 2:117. It reframes the irritation as a taklif, which is a much better handle than \"be patient.\"","Prayer at its time, in front of the children. ✅ It is the first of the three tests (al-Khisal p.103 h.62), and it is the only one of the three a small child can actually observe you passing.","Zero imtinan for twenty-four hours. No \"after everything I've done for you,\" no \"do you know how long I spent on this,\" no reminding a child of a favour. ⚠ Count your slips for the first three days; most parents are surprised.","When a child helps you, notice what you feel — gladness or wariness [52:22]. Do not act on it; just log it. It is the single best diagnostic in the lecture."],"questions":{"parent":["When my child does something for me unasked, what is my first internal reaction — gladness or wariness? [52:22] What does that tell me about what I have built so far?","In the last month, how many times have I reminded one of my children of something I did for them? Would Q 2:264 apply to those reminders?","When was the last time my children saw me help someone who could not repay me?"],"spouse":["Which of us models mudara better, and which of us do the children copy?","Do we run a ledger with each other? Do the children hear it?","When we disagree about how much to give — money, time, hospitality — what is the real disagreement underneath?"],"family":["What is the difference between sadaqa and muwasat? (Answer: one goes down, one goes across.)","If someone is unkind to you and later needs your help, what should you do — and why is that hard?","Imam al-Kazim (a) gave the man who insulted his grandfather more money than the man had hoped for. Why do you think he did that instead of arguing with him?"]},"activities":{"abbas":["The Two Loaves (story + discussion, 12 minutes)","\"He's Had a Long Day\" (character-building, ongoing, 30 seconds at a time)","Which Was Better? (the Imam al-Kazim method, 10 minutes, repeatable forever)","Not Your Seat (real-life challenge, all week, deliberately boring)","Your Own Money (character-building, one month)","The Debt That Goes Both Ways (Arabic + character, 15 minutes)","The Blessing Nobody Wants (discussion, 8 minutes, at dinner)"],"eliyya":["The Coat (play-based, 6 minutes)","Sharing Across, Not Down (Islamic manners, 5 minutes, at snack time)","Someone Else Goes First (emotional development, all week, tiny)","The Secret Job (parent–child bonding, 10 minutes, before anyone is up)","The Gift for Grandpa (Islamic manners, 3 minutes)","The Bad-Breath Girl (play-based, 5 minutes, with toys)","Needs Are Presents (emotional development, ongoing, one sentence)"]},"corrections":[{"claim":"Dead rejoice at istighfar \"as the living at a gift\"","status":"⚠ Moderately verified","note":"Bihar 79:62; introduced «رُوِيَ» — chainless, no Imam named"},{"claim":"Dead can see their place in paradise and pray to arrive sooner","status":"⚠ Not in the quoted text","note":"Different narration family — separate them"},{"claim":"Prophet (s) forbade praying for death","status":"✅ content correct / ⚠ Sunni","note":"Bukhari 5671, Muslim 2680 (sahih). No Imami primary located. The prohibition is on wishing death out of distress"},{"claim":"Best legacy = righteous child doing istighfar","status":"⚠ Ranking not in the Imami text","note":"Three legacies: child is third (Bihar 71:257; Muslim 1631). Child is first only in the Sunni Ibn Majah version. ⭐ Substitute: al-Kafi 7:57"},{"claim":"\"Allah is karim and loves karam\"","status":"✅ Strongly verified","note":"Prophetic; sahih bi-shawahidihi — al-Arna'ut named. ⚠ Sunni grading; second clause dropped"},{"claim":"Litmus test: «من لم يجاز الإساءة بالإحسان…»","status":"⚠ Chainless — but ⭐ correctly attributed","note":"Ghurar al-Hikam 8958. ⭐ Part 15 gave the same line to the Prophet (s); this attribution is the right one. Verse anchor: Q 41:34"}],"counts":{"verses":3,"narrations":25,"audit":46}}];
